// Generated from data/topic-*.json — edit those, then regenerate.
export const SHIPPED = [{"id":"topic_adages_puns","title":"Adages & Puns","short":"Adages & Puns","state":"TX","grade":5,"domain":"Foundational Language","standards":["5.3D"],"blurb":"Two skills — sayings that teach a lesson, and words doing two jobs at once — then one full-topic proof.","icon":"🐱","core":[{"id":"ap_adages","title":"Adages","standards":["5.3D"],"skill":"What an adage means, and how the story around it tells you","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions. The sentences are numbered.","sentences":["Mina spent three weeks building a volcano for the science fair.","She painted it gray and added fake lava with glue and glitter gel.","The night before the competition, she proudly placed it on the kitchen table.","Her little brother Ben accidentally bumped the table while running through the room.","The volcano crashed, and pieces scattered everywhere.","Mina groaned, “My project is ruined!”","Her dad handed her tape and said, “You can’t cry over spilled milk.”","Mina realized she needed to stop worrying about the accident and focus on fixing the problem.","She repaired the volcano as best she could.","It wasn’t perfect, but it still erupted bright orange foam during judging."],"hint":"The sentence right after the adage usually tells you what it did.","questions":[{"kind":"write","sentence":7,"ask":"What does “You can’t cry over spilled milk” mean in the passage?","checks":[{"label":"Says the thing has already happened","rule":{"type":"any","of":[{"type":"contains","any":["already happened"]},{"type":"contains","any":["cannot change"]},{"type":"contains","any":["can’t change"]},{"type":"contains","any":["can't change"]},{"type":"contains","any":["in the past"]},{"type":"contains","any":["done"]}]}},{"label":"Says being upset does not help","rule":{"type":"any","of":[{"type":"contains","any":["no point"]},{"type":"contains","any":["no use"]},{"type":"contains","any":["does not help"]},{"type":"contains","any":["upset"]},{"type":"contains","any":["worry"]},{"type":"contains","any":["crying"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"It means there is no point being upset about something that has already happened, because you cannot change it.","video":"ap_adages-1"},{"kind":"blank","sentence":8,"ask":"Which sentence BEST helps a reader understand what the adage means?","answer":"Mina realized she needed to stop worrying about the accident and focus on fixing the problem.","options":["The volcano crashed, and pieces scattered everywhere.","Mina realized she needed to stop worrying about the accident and focus on fixing the problem.","She repaired the volcano as best she could.","Mina groaned, “My project is ruined!”"],"video":"ap_adages-2"},{"kind":"write","sentence":7,"ask":"Finish the sentence: Mina’s dad most likely used the adage to…","checks":[{"label":"Says what he wanted her to do","rule":{"type":"any","of":[{"type":"contains","any":["focus"]},{"type":"contains","any":["fix"]},{"type":"contains","any":["move on"]},{"type":"contains","any":["keep going"]}]}},{"label":"Mentions the feeling he was answering","rule":{"type":"any","of":[{"type":"contains","any":["upset"]},{"type":"contains","any":["worry"]},{"type":"contains","any":["sad"]},{"type":"contains","any":["feeling"]},{"type":"contains","any":["disappoint"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"encourage Mina to focus on fixing the problem instead of feeling upset","video":"ap_adages-3"}]},{"kind":"passage","brief":"A second passage. Same job.","sentences":["During lunch, Jordan noticed a container labeled DO NOT OPEN sitting alone on the cafeteria table.","Curious about what was inside, he slowly lifted the lid.","Inside was a tuna sandwich and a banana covered in peanut butter.","At that moment, the owner walked over and frowned.","Mia laughed and said, “Curiosity killed the cat.”","Jordan quickly closed the container and decided some mysteries should stay mysteries."],"hint":"What happened to Jordan right after he got curious?","questions":[{"kind":"write","sentence":5,"ask":"What does the adage “Curiosity killed the cat” mean in this passage?","checks":[{"label":"Mentions being curious","rule":{"type":"any","of":[{"type":"contains","any":["curious"]},{"type":"contains","any":["curiosity"]},{"type":"contains","any":["nosy"]}]}},{"label":"Says where it leads","rule":{"type":"any","of":[{"type":"contains","any":["trouble"]},{"type":"contains","any":["problem"]},{"type":"contains","any":["should not"]},{"type":"contains","any":["shouldn’t"]},{"type":"contains","any":["shouldn't"]},{"type":"contains","any":["mind your own"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"It means being too curious about something that is not yours can get you into trouble.","video":"ap_adages-4"}]},{"kind":"fix","mode":"select","brief":"Each cat agent explains an adage. Say whether the explanation is right.","bank":[],"hint":"Read the explanation on its own. Does it actually say what the adage says?","items":[{"given":"“Actions speak louder than words.” — People’s behavior shows more than what they say.  →  ____","answer":"right","options":["right","wrong"],"video":"ap_adages-5"},{"given":"“Don’t judge a book by its cover.” — Books with nice covers are usually interesting.  →  ____","answer":"wrong","options":["right","wrong"],"video":"ap_adages-6"},{"given":"“The early bird catches the worm.” — People who prepare early often have an advantage.  →  ____","answer":"right","options":["right","wrong"],"video":"ap_adages-7"},{"given":"“Practice makes perfect.” — Only talented people become successful.  →  ____","answer":"wrong","options":["right","wrong"],"video":"ap_adages-8"}]},{"kind":"fix","mode":"select","brief":"Each correct cat agent carries a clue word. The suspect has all of them.","bank":[],"hint":"Only the agents who explained their adage correctly count.","items":[{"given":"Actions speak louder than words → Backpack.  Don’t judge a book by its cover → Camera.  The early bird catches the worm → Watch.  Practice makes perfect → Sandals.  What is the suspect carrying?  ____","answer":"a backpack and a watch","options":["a camera and sandals","a backpack and a watch","a camera and a watch","a backpack and sandals"],"video":"ap_adages-9"}]},{"kind":"passage","brief":"One more passage.","sentences":["Kayla had practiced for weeks before the school spelling bee and expected to reach the championship round easily.","However, during the final round, she misspelled a simple word she had reviewed many times before the competition.","Frustrated by her mistake, Kayla told her coach that entering the contest had been a waste of time.","Her coach simply replied, “Every cloud has a silver lining.”","Several days later, Kayla received an email inviting her to join the district vocabulary team based on her earlier performance scores.","Although she still remembered the disappointment of the spelling bee, she began to view the experience differently."],"hint":"Find the saying first, then work out what it did for Kayla.","questions":[{"kind":"blank","sentence":4,"ask":"Which words in sentence 4 are the adage?","answer":"Every cloud has a silver lining","options":["Her coach simply replied","Every cloud has a silver lining","a waste of time","the championship round"],"video":"ap_adages-10"},{"kind":"blank","sentence":4,"ask":"What is the meaning of the adage in this paragraph?","answer":"Disappointing situations can still lead to something positive.","options":["Practicing for competitions always leads to success.","Disappointing situations can still lead to something positive.","Vocabulary teams are harder than spelling bees.","Coaches should encourage students after contests."],"video":"ap_adages-11"}]}]},{"id":"ap_puns","title":"Puns","standards":["5.3D"],"skill":"Spotting a word doing two jobs at once, and saying what both are","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions. The sentences are numbered.","sentences":["Last Saturday, Andrea helped her Uncle Mateo at his bakery during the town food festival.","Business was slow at first, so her uncle tried using silly jokes to attract customers.","As people walked by, he held up a loaf of bread and shouted, “I loaf making customers smile!”","Then he pointed to a tray of pastries and said, “We always rise to the occasion!”","A few people laughed and stopped at the booth.","Later, when someone asked why the bakery stayed open so late, he replied, “That’s just how we roll.”","Soon, customers crowded around the booth laughing at the jokes while buying cookies, muffins, and warm cinnamon rolls."],"hint":"A pun is one word doing two jobs. Say both jobs out loud.","questions":[{"kind":"blank","sentence":3,"ask":"Which pun means the baker enjoys making people happy?","answer":"I loaf making customers smile!","options":["I loaf making customers smile!","We always rise to the occasion!","That’s just how we roll."],"video":"ap_puns-1"},{"kind":"pick","sentence":4,"ask":"Click the word in sentence 4 that creates the pun, then write the other thing it means.","target":"rise","answer":"dough rising","video":"ap_puns-2"},{"kind":"write","sentence":4,"ask":"Why is that pun funny?","checks":[{"label":"Mentions the bread meaning","rule":{"type":"any","of":[{"type":"contains","any":["dough"]},{"type":"contains","any":["bread"]},{"type":"contains","any":["bake"]},{"type":"contains","any":["rising"]}]}},{"label":"Mentions the other meaning","rule":{"type":"any","of":[{"type":"contains","any":["occasion"]},{"type":"contains","any":["challenge"]},{"type":"contains","any":["do well"]},{"type":"contains","any":["succeed"]},{"type":"contains","any":["meet"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"It is funny because bread dough really does rise, and rising to the occasion also means doing well when something is asked of you.","video":"ap_puns-3"},{"kind":"write","sentence":6,"ask":"Why is “That’s just how we roll” a pun?","checks":[{"label":"Mentions rolls the food","rule":{"type":"any","of":[{"type":"contains","any":["roll"]},{"type":"contains","any":["bread"]},{"type":"contains","any":["bun"]},{"type":"contains","any":["dough"]}]}},{"label":"Mentions the saying","rule":{"type":"any","of":[{"type":"contains","any":["how we do"]},{"type":"contains","any":["the way we"]},{"type":"contains","any":["saying"]},{"type":"contains","any":["act"]},{"type":"contains","any":["behave"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"A bakery sells rolls, and “how we roll” is also a saying that means the way we do things.","video":"ap_puns-4"},{"kind":"blank","sentence":7,"ask":"Which line could the author use in an advertisement for the bakery?","answer":"“Our bakers knead your support!”","options":["“Our bakers knead your support!”","“The bakery opens every morning at six.”","“Fresh bread is sold daily at the festival.”","“Customers lined up near the front door.”"],"video":"ap_puns-5"}]},{"kind":"passage","brief":"A cave, a dragon, and some very bad jokes.","sentences":["Liora wandered cautiously through the glowing forest until she discovered a hidden cave behind tangled vines.","Glittering crystals reflected shimmering patterns of light across the rocky floor as she ventured deeper inside.","Soon, she noticed unusual wooden signs hanging beside the tunnels.","One sign pointed toward a rocky passage and read, “This cave is ore-some!”","Another sign beside a pile of gems declared, “You really rock!”","Liora chuckled at the clever signs, but her smile quickly faded when a deep growl echoed through the cavern.","A dragon stepped from the shadows and narrowed its glowing eyes.","“I hope you didn’t take my jokes for granite,” the dragon warned as smoke curled from its nose."],"hint":"Read the dragon’s line out loud and listen for the word underneath it.","questions":[{"kind":"blank","sentence":4,"ask":"What is the meaning of the pun “This cave is ore-some!”?","answer":"The cave is exciting and impressive.","options":["The cave is exciting and impressive.","The cave is filled with loud noises.","The cave is dangerous to enter.","The cave is difficult to explore."],"video":"ap_puns-6"},{"kind":"pick","sentence":8,"ask":"Click the pun in the dragon’s warning, then write the word it is playing on.","target":"granite","answer":"granted","video":"ap_puns-7"},{"kind":"write","sentence":8,"ask":"Explain the dragon’s pun.","checks":[{"label":"Names the rock","rule":{"type":"contains","any":["granite"]}},{"label":"Names the word underneath","rule":{"type":"any","of":[{"type":"contains","any":["granted"]},{"type":"contains","any":["for grant"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"Granite is a rock found in a cave, and it sounds like granted, so the dragon is asking them not to take its jokes for granted.","video":"ap_puns-8"}]},{"kind":"passage","brief":"One more. Read it, then answer.","sentences":["Jordan volunteered at the town garden center during the spring festival.","As he carried pots of colorful flowers to the display tables, the manager smiled and said, “I’m rooting for you today!”","Jordan laughed at the joke and continued helping customers choose plants.","Bright rows of tulips and roses filled the air with a fresh scent.","Later, a customer accidentally knocked over a watering can, spilling water across the floor.","The manager handed her a towel and said, “No need to wet your plants over it!”","The customers chuckled while Jordan realized the manager enjoyed using puns to make people smile."],"hint":"Roots grow in soil. What else does rooting mean?","questions":[{"kind":"blank","sentence":2,"ask":"Mikey thinks sentence 2 contains a pun. Do you agree?","answer":"Agree","options":["Agree","Disagree"],"video":"ap_puns-9"},{"kind":"write","sentence":2,"ask":"Explain your reasoning.","checks":[{"label":"Mentions the plant meaning","rule":{"type":"any","of":[{"type":"contains","any":["root"]},{"type":"contains","any":["plant"]},{"type":"contains","any":["garden"]},{"type":"contains","any":["soil"]}]}},{"label":"Mentions cheering someone on","rule":{"type":"any","of":[{"type":"contains","any":["cheer"]},{"type":"contains","any":["support"]},{"type":"contains","any":["encourag"]},{"type":"contains","any":["hoping"]},{"type":"contains","any":["want"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"It is a pun because rooting means cheering someone on, and roots are also part of the plants they sell at the garden centre.","video":"ap_puns-10"}]}]}],"skillBuilders":{"ap_adages":{"id":"ap_sb_adages","title":"SB: Adages","standards":["5.3D"],"skill":"Matching a saying to what it actually means","activities":[{"kind":"fix","mode":"select","bank":[],"brief":"Read each short story. Choose the meaning of the adage it uses.","hint":"Ask what the character did wrong, or did right.","items":[{"given":"Mateo carried six heavy boxes at once instead of making two trips, and dropped them all. The coach said, “Slow and steady wins the race.”  →  ____","answer":"Careful, steady effort works best.","options":["Careful, steady effort works best.","Rushing can cause mistakes.","Do not assume success before it happens.","Taking a risk can lead to a reward."],"video":"ap_sb_adages-1"},{"given":"Ava rushed through her science project the night before it was due, and parts fell apart in class. Her brother said, “Haste makes waste.”  →  ____","answer":"Rushing can cause mistakes.","options":["Careful, steady effort works best.","Rushing can cause mistakes.","Do not assume success before it happens.","Taking a risk can lead to a reward."],"video":"ap_sb_adages-2"},{"given":"Jordan bragged he would win first place at the talent show. His teacher warned, “Don’t count your chickens before they hatch.”  →  ____","answer":"Do not assume success before it happens.","options":["Careful, steady effort works best.","Rushing can cause mistakes.","Do not assume success before it happens.","Taking a risk can lead to a reward."],"video":"ap_sb_adages-3"},{"given":"Leila felt nervous about joining robotics club, went anyway, and made new friends. Her grandmother said, “Nothing ventured, nothing gained.”  →  ____","answer":"Taking a risk can lead to a reward.","options":["Careful, steady effort works best.","Rushing can cause mistakes.","Do not assume success before it happens.","Taking a risk can lead to a reward."],"video":"ap_sb_adages-4"}]},{"kind":"passage","brief":"Read the passage, then answer.","sentences":["Carter had waited all season for the championship basketball game.","On the morning of the tournament, he packed his water bottle, shoes, and lucky wristband before heading to school.","However, when his team arrived at the gym, Carter realized he had forgotten his basketball jersey at home.","“I can’t believe this happened,” Carter groaned as he searched through his backpack again.","His coach handed him a practice jersey and reminded him, “Look before you leap.”","Coach Daniels explained that Carter had rushed out the door without checking his equipment carefully.","Embarrassed, Carter quickly joined warm-ups and promised himself he would prepare more carefully next time."],"hint":"The sentence after the adage usually explains it.","questions":[{"kind":"blank","sentence":5,"ask":"Which words in sentence 5 are the adage?","answer":"Look before you leap","options":["His coach handed him a practice jersey","Look before you leap","reminded him"],"video":"ap_sb_adages-5"},{"kind":"blank","sentence":6,"ask":"What does that adage mean?","answer":"People should think carefully before acting too quickly.","options":["Basketball players should always arrive early for games.","People should think carefully before acting too quickly.","Championship games are difficult to prepare for."],"video":"ap_sb_adages-6"}]},{"kind":"passage","brief":"One more passage.","sentences":["Fiona hurried through the crowded school hallway carrying posters for the student council fundraiser.","Earlier that morning, her teacher had reminded the class, “Better safe than sorry,” but Fiona ignored the advice and stacked too many supplies in her arms at once.","As she rushed toward the cafeteria, several posters slipped onto the floor and scattered everywhere.","Her friend Malik helped gather the papers and reminded her, “Pride comes before a fall.”","Embarrassed, Fiona nodded and carried the remaining supplies more carefully the rest of the afternoon."],"hint":"Two sayings, two different lessons.","questions":[{"kind":"blank","sentence":2,"ask":"Which detail best shows why “Better safe than sorry” applied to Fiona?","answer":"She stacked too many supplies in her arms at once.","options":["She stacked too many supplies in her arms at once.","She was carrying posters for the fundraiser.","Malik helped gather the papers."],"video":"ap_sb_adages-7"},{"kind":"write","sentence":4,"ask":"What does the adage “Pride comes before a fall” mean?","checks":[{"label":"Mentions being overconfident","rule":{"type":"any","of":[{"type":"contains","any":["proud"]},{"type":"contains","any":["pride"]},{"type":"contains","any":["confiden"]},{"type":"contains","any":["boast"]},{"type":"contains","any":["show off"]},{"type":"contains","any":["sure of"]}]}},{"label":"Mentions what follows","rule":{"type":"any","of":[{"type":"contains","any":["mistake"]},{"type":"contains","any":["fail"]},{"type":"contains","any":["fall"]},{"type":"contains","any":["wrong"]},{"type":"contains","any":["trouble"]},{"type":"contains","any":["embarrass"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"It means being too proud or too sure of yourself often comes right before you make a mistake.","video":"ap_sb_adages-8"}]}]},"ap_puns":{"id":"ap_sb_puns","title":"SB: Puns","standards":["5.3D"],"skill":"Telling a pun from an ordinary sentence, one at a time","activities":[{"kind":"fix","mode":"select","bank":[],"brief":"Does the sentence contain a pun?","hint":"A pun has a word doing two jobs. An ordinary sentence does not.","items":[{"given":"A baker opens a shop that is rolling in dough.  →  ____","answer":"pun","options":["pun","not a pun"],"video":"ap_sb_puns-1"},{"given":"A gardener watered the flowers early every morning.  →  ____","answer":"not a pun","options":["pun","not a pun"],"video":"ap_sb_puns-2"},{"given":"A fisherman opens a seafood restaurant and says the business is off the hook.  →  ____","answer":"pun","options":["pun","not a pun"],"video":"ap_sb_puns-3"},{"given":"A cat becomes famous for its purr-fect singing voice.  →  ____","answer":"pun","options":["pun","not a pun"],"video":"ap_sb_puns-4"},{"given":"A scientist completed an experiment in the chemistry lab.  →  ____","answer":"not a pun","options":["pun","not a pun"],"video":"ap_sb_puns-5"},{"given":"The sunburned banana said, “I’m peeling terrible today!”  →  ____","answer":"pun","options":["pun","not a pun"],"video":"ap_sb_puns-6"}]},{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Sean helped his dad at the town bakery during the weekend festival.","As customers lined up for fresh bread, his dad smiled and said, “Business is really rolling today!”","Sean laughed because the word rolling referred to both bread dough and the busy crowd.","Later, a customer asked whether the bakery stayed busy every weekend.","His dad grinned and replied, “We always rise to the occasion.”","Soon, more families gathered around the booth to buy pastries and listen to the bakery jokes.","Sean carried trays of cupcakes to the front table while customers crowded around the bakery booth.","A customer asked if the bakery stayed busy every weekend, and Sean’s dad smiled and said, “Business is really crumby today!”","Sean laughed as more families stopped by to buy desserts and hear the bakery jokes."],"hint":"Sentence 3 tells you how a pun works. Use the same idea on the others.","questions":[{"kind":"write","sentence":2,"ask":"Explain what “Business is really rolling today!” means.","checks":[{"label":"Mentions the bakery meaning","rule":{"type":"any","of":[{"type":"contains","any":["roll"]},{"type":"contains","any":["dough"]},{"type":"contains","any":["bread"]},{"type":"contains","any":["bake"]}]}},{"label":"Mentions business going well","rule":{"type":"any","of":[{"type":"contains","any":["busy"]},{"type":"contains","any":["going well"]},{"type":"contains","any":["lots of customers"]},{"type":"contains","any":["crowd"]},{"type":"contains","any":["good"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"A bakery rolls dough, and business rolling along also means it is busy and going well.","video":"ap_sb_puns-7"},{"kind":"blank","sentence":5,"ask":"What is the meaning of the pun in sentence 5?","answer":"The phrase refers to bread dough rising and succeeding during challenges.","options":["The bakery opens early each morning for customers.","The phrase refers to bread dough rising and succeeding during challenges.","The bakery sells fresh bread during weekend festivals."],"video":"ap_sb_puns-8"},{"kind":"pick","sentence":8,"ask":"Click the word in sentence 8 that creates the pun, then write the word it sounds like.","target":"crumby","answer":"crummy","video":"ap_sb_puns-9"},{"kind":"write","sentence":8,"ask":"Explain the pun in sentence 8.","checks":[{"label":"Mentions crumbs","rule":{"type":"any","of":[{"type":"contains","any":["crumb"]},{"type":"contains","any":["cake"]},{"type":"contains","any":["bread"]},{"type":"contains","any":["bakery"]}]}},{"label":"Mentions the other meaning","rule":{"type":"any","of":[{"type":"contains","any":["crummy"]},{"type":"contains","any":["bad"]},{"type":"contains","any":["terrible"]},{"type":"contains","any":["poor"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"Baked goods leave crumbs, and crumby sounds like crummy, which means bad — so it is a joke about business being both.","video":"ap_sb_puns-10"}]}]}},"full":{"id":"ap_full","title":"Full Topic: Adages & Puns","standards":["5.3D"],"skill":"Both skills, in one piece of writing","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Heavy snow covered the sidewalks and roads across Maple Lane.","Mila and her younger brother Theo bundled into thick coats and hurried outside to help shovel the driveway.","As Theo slipped into a snowbank, he laughed, “I guess I really broke the ice today!”","Mila groaned at the joke but helped him back up.","After several minutes of shoveling, Mila complained that clearing the snow would take forever.","Their grandfather smiled and reminded them, “Many hands make light work.”","Soon, several neighbors joined together, passing shovels back and forth while laughing and talking."],"hint":"One of these is a joke about words. One is a lesson about life.","questions":[{"kind":"blank","sentence":3,"ask":"Which line in the passage is the pun?","answer":"I guess I really broke the ice today!","options":["I guess I really broke the ice today!","Many hands make light work.","clearing the snow would take forever"],"video":"ap_full-1"},{"kind":"blank","sentence":6,"ask":"Which line in the passage is the adage?","answer":"Many hands make light work.","options":["I guess I really broke the ice today!","Many hands make light work.","passing shovels back and forth"],"video":"ap_full-2"},{"kind":"write","sentence":3,"ask":"What is the meaning of the pun?","checks":[{"label":"Mentions the literal ice","rule":{"type":"any","of":[{"type":"contains","any":["ice"]},{"type":"contains","any":["snow"]},{"type":"contains","any":["slipped"]},{"type":"contains","any":["fell"]}]}},{"label":"Mentions the saying","rule":{"type":"any","of":[{"type":"contains","any":["break the ice"]},{"type":"contains","any":["broke the ice"]},{"type":"contains","any":["awkward"]},{"type":"contains","any":["start"]},{"type":"contains","any":["joke"]},{"type":"contains","any":["friendly"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"Theo really did fall into the ice and snow, and breaking the ice also means starting things off in a friendly way.","video":"ap_full-3"},{"kind":"write","sentence":6,"ask":"What is the meaning of the adage?","checks":[{"label":"Mentions more people","rule":{"type":"any","of":[{"type":"contains","any":["people"]},{"type":"contains","any":["everyone"]},{"type":"contains","any":["help"]},{"type":"contains","any":["together"]},{"type":"contains","any":["hands"]}]}},{"label":"Mentions the work being easier","rule":{"type":"any","of":[{"type":"contains","any":["easier"]},{"type":"contains","any":["faster"]},{"type":"contains","any":["quicker"]},{"type":"contains","any":["less work"]},{"type":"contains","any":["lighter"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"It means a job gets easier and faster when more people help with it.","video":"ap_full-4"},{"kind":"pick","sentence":3,"ask":"Theo says another joke: “Ice to meet this snowstorm!” Click the word in sentence 3 that his new joke plays on, then write the word it sounds like.","target":"ice","answer":"nice","video":"ap_full-5"}]},{"kind":"passage","brief":"A second passage. Same two skills.","sentences":["Dark clouds rolled across Cedar Street as rain poured onto the sidewalks and driveways.","Jada and her cousin Marcus hurried outside to help bring in groceries before the storm became worse.","As Marcus slipped while carrying a bag of apples, he laughed and shouted, “Orange you glad I didn’t drop these?”","Jada groaned at the joke but grabbed the bag before it rolled into a puddle.","A few minutes later, the power suddenly went out across the neighborhood.","Jada worried that dinner would be ruined, but her grandmother calmly lit several candles and said, “When life gives you lemons, make lemonade.”","Soon, the family gathered around the kitchen table telling stories and playing card games while rain tapped against the windows."],"hint":"Say the fruit out loud and listen for the ordinary word inside it.","questions":[{"kind":"pick","sentence":3,"ask":"Click the word that makes Marcus’s joke a pun, then write the word it sounds like.","target":"Orange","answer":"aren’t","video":"ap_full-7"},{"kind":"blank","sentence":3,"ask":"What is the meaning of that pun?","answer":"Marcus uses the word orange to sound like aren’t while joking about the apples.","options":["Marcus uses the word orange to sound like aren’t while joking about the apples.","Marcus believes oranges are better than apples.","Marcus wants Jada to buy more fruit from the store.","Marcus thinks the groceries are too heavy to carry."],"video":"ap_full-8"},{"kind":"write","sentence":6,"ask":"Explain the meaning of “When life gives you lemons, make lemonade.”","checks":[{"label":"Mentions something going wrong","rule":{"type":"any","of":[{"type":"contains","any":["bad"]},{"type":"contains","any":["wrong"]},{"type":"contains","any":["problem"]},{"type":"contains","any":["difficult"]},{"type":"contains","any":["hard"]},{"type":"contains","any":["lemons"]}]}},{"label":"Mentions making it good","rule":{"type":"any","of":[{"type":"contains","any":["best"]},{"type":"contains","any":["good"]},{"type":"contains","any":["positive"]},{"type":"contains","any":["better"]},{"type":"contains","any":["lemonade"]},{"type":"contains","any":["opportunit"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"It means that when something bad happens you should make the best of it and find something good in it.","video":"ap_full-9"}]},{"kind":"passage","brief":"A last passage.","sentences":["Caleb helped his aunt prepare decorations for the school fundraiser after classes ended.","While they hung colorful banners across the cafeteria, his aunt reminded him, “Don’t put all your eggs in one basket.”","Caleb nodded and continued organizing supplies for different games and activities.","Soon, students arrived with baked goods, raffle prizes, and posters for the event.","Later, one table collapsed, sending markers and papers sliding across the floor.","Caleb quickly helped clean the mess while his aunt smiled proudly at how calmly he handled the problem.","By evening, the fundraiser looked organized and ready to begin."],"hint":"Is it a saying with a lesson in it, or just an instruction?","questions":[{"kind":"blank","sentence":2,"ask":"Lyla thinks sentence 2 contains an adage. Do you agree?","answer":"Agree","options":["Agree","Disagree"],"video":"ap_full-10"},{"kind":"write","sentence":2,"ask":"Explain your reasoning.","checks":[{"label":"Says it is an adage or a saying","rule":{"type":"any","of":[{"type":"contains","any":["adage"]},{"type":"contains","any":["saying"]},{"type":"contains","any":["adages"]}]}},{"label":"Says what it means","rule":{"type":"any","of":[{"type":"contains","any":["one place"]},{"type":"contains","any":["spread"]},{"type":"contains","any":["everything on"]},{"type":"contains","any":["risk"]},{"type":"contains","any":["all your"]},{"type":"contains","any":["depend"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"It is an adage because it is a well-known saying that teaches a lesson: do not risk everything on one plan.","video":"ap_full-11"}]}]}},{"id":"topic_analyze_text","title":"Analyze a Text","short":"Analyze a Text","state":"TX","grade":5,"domain":"Multiple Genres","standards":["5.8B","5.8C","5.8D"],"blurb":"Setting, plot and relationships — three skills, then one full-topic proof.","icon":"🔍","core":[{"id":"at_setting","title":"How Setting Influences Plot","standards":["5.8D"],"skill":"Where and when a story happens, and what that does to it","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions. The sentences are numbered.","sentences":["Twelve-year-old Mai visited her grandparents in Vietnam, where they stayed in a historic town known for its colorful lantern festivals.","Each month, families gathered along the river after sunset to celebrate traditions that had been passed down for generations.","On the evening of the festival, Mai was responsible for delivering handmade lanterns to her aunt’s booth before the celebration began.","As she used her GPS to hurry through the crowded streets, a sudden rainstorm swept into town.","Vendors rushed to cover their displays, and many of the narrow pathways became slippery and difficult to cross.","Mai carefully protected the lanterns beneath a woven basket and searched for a safer route.","She remembered a covered walkway merchants often used during bad weather and followed it to the riverfront.","When she arrived, the lanterns were dry and ready to be displayed.","As darkness fell, hundreds of glowing lanterns reflected across the water, and Mai felt proud that she had helped preserve an important community tradition."],"hint":"Setting is where AND when. One sentence tells you the country; one word tells you the century.","questions":[{"kind":"blank","sentence":1,"ask":"Which country is the story set in?","answer":"Vietnam","options":["Vietnam","Peru","Morocco","Thailand"]},{"kind":"pick","sentence":4,"ask":"Click the word in sentence 4 that tells you this story is modern, then write which century that makes it.","target":"GPS","answer":"twenty-first"},{"kind":"blank","sentence":2,"ask":"Which detail is a cultural element of the story?","answer":"Families gather for a festival that celebrates traditions.","options":["Mai searches for a covered walkway during the storm.","Rain makes the streets slippery and difficult to cross.","Families gather for a festival that celebrates traditions.","Mai carries the lanterns beneath a woven basket."]},{"kind":"write","sentence":5,"ask":"How does the setting add difficulty to the story?","checks":[{"label":"Names what the setting did","rule":{"type":"any","of":[{"type":"contains","any":["rain"]},{"type":"contains","any":["storm"]},{"type":"contains","any":["slippery"]},{"type":"contains","any":["wet"]}]}},{"label":"Says what it made hard","rule":{"type":"any","of":[{"type":"contains","any":["cross"]},{"type":"contains","any":["path"]},{"type":"contains","any":["street"]},{"type":"contains","any":["walk"]},{"type":"contains","any":["deliver"]},{"type":"contains","any":["route"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"A sudden rainstorm made the narrow pathways slippery and difficult to cross, so Mai had to find another route to deliver the lanterns."},{"kind":"write","sentence":4,"ask":"Finish the sentence: the time period affects the challenges Mai faces by…","checks":[{"label":"Says she does it herself","rule":{"type":"any","of":[{"type":"contains","any":["herself"]},{"type":"contains","any":["her own"]},{"type":"contains","any":["carry"]},{"type":"contains","any":["deliver"]},{"type":"contains","any":["protect"]}]}},{"label":"Mentions modern services or technology","rule":{"type":"any","of":[{"type":"contains","any":["delivery"]},{"type":"contains","any":["technology"]},{"type":"contains","any":["gps"]},{"type":"contains","any":["modern"]},{"type":"contains","any":["phone"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"In 2008 Mai must protect and deliver the lanterns herself during the storm instead of relying on modern delivery services or technology."}]},{"kind":"fix","mode":"select","bank":[],"brief":"Read each excerpt. Which time period is it most likely set in?","hint":"Look for the technology, or the lack of it. You may use an answer more than once.","items":[{"given":"Scientists aboard an ocean research station used advanced sensors to track changes in marine ecosystems.  →  ____","answer":"Future","options":["Middle Ages","Twenty-First Century","Future"]},{"given":"During the community meeting, residents reviewed digital maps showing proposed changes to local parks.  →  ____","answer":"Twenty-First Century","options":["Middle Ages","Twenty-First Century","Future"]},{"given":"Merchants crowded the marketplace during the annual trade fair, displaying wool, spices, and handmade pottery.  →  ____","answer":"Middle Ages","options":["Middle Ages","Twenty-First Century","Future"]},{"given":"Scribes spent months carefully copying texts by hand, making each book rare and expensive.  →  ____","answer":"Middle Ages","options":["Middle Ages","Twenty-First Century","Future"]}]},{"kind":"passage","brief":"One more passage.","sentences":["Amina belonged to the Tuareg people, and lived near the Sahara Desert in North Africa.","Each year, her community held a festival where families shared traditional music, stories, and handcrafted goods.","This year, Amina helped prepare an exhibit of silver jewelry and woven mats.","On the morning of the festival, strong desert winds covered many display signs with sand.","Amina and her cousins cleaned the exhibits and replaced the damaged labels before visitors arrived.","By afternoon, people from nearby communities explored the festival and learned about Tuareg traditions.","Amina felt proud to help share her culture with others."],"hint":"Cultural setting is what the people of a place do, not what the weather does.","questions":[{"kind":"blank","sentence":2,"ask":"Which sentence best establishes the cultural setting?","answer":"Families shared traditional music, stories, and handcrafted goods.","options":["Families shared traditional music, stories, and handcrafted goods.","Strong desert winds covered many display signs with sand.","People from nearby communities explored the festival."]},{"kind":"write","sentence":5,"ask":"How does the cultural setting influence Amina’s actions?","checks":[{"label":"Says what she does","rule":{"type":"any","of":[{"type":"contains","any":["prepare"]},{"type":"contains","any":["exhibit"]},{"type":"contains","any":["clean"]},{"type":"contains","any":["help"]},{"type":"contains","any":["replace"]}]}},{"label":"Connects it to her culture","rule":{"type":"any","of":[{"type":"contains","any":["tuareg"]},{"type":"contains","any":["tradition"]},{"type":"contains","any":["culture"]},{"type":"contains","any":["festival"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"The cultural setting influences Amina because she helps prepare exhibits and preserve Tuareg traditions for the festival."},{"kind":"blank","sentence":6,"ask":"Which detail best shows the importance of cultural traditions?","answer":"People from nearby communities explored the festival and learned about Tuareg traditions.","options":["Strong desert winds covered many display signs with sand.","People from nearby communities explored the festival and learned about Tuareg traditions.","Amina helped prepare an exhibit of silver jewelry and woven mats."]}]}]},{"id":"at_plot","title":"Plot Elements","standards":["5.8C"],"skill":"The parts of a story, and what each one is doing","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Every spring, the town hosted a seed exchange where gardeners traded seeds they had saved from the previous year’s harvest.","This year, Kieran volunteered to organize the event for the first time.","He spent weeks labeling envelopes, arranging tables, and creating signs so visitors could easily find what they needed.","On the morning of the exchange, Kieran unlocked the community center and froze.","Several boxes of seed packets had been stacked in the wrong sections.","Tomatoes were mixed with peppers, herbs were scattered among flower seeds, and people were already beginning to arrive.","“Start with one table,” Mrs. Navarro suggested. “You don’t have to fix everything at once.”","Kieran took a deep breath and began sorting.","A few visitors noticed the confusion and offered to help.","By opening time, every packet was in the correct place, and Kieran felt proud that he’d been able to solve the problem calmly."],"hint":"Tension is built by what goes wrong, and by the clock running.","questions":[{"kind":"write","sentence":6,"ask":"How does the author create tension before the seed exchange begins?","checks":[{"label":"Names what went wrong","rule":{"type":"any","of":[{"type":"contains","any":["wrong section"]},{"type":"contains","any":["mixed"]},{"type":"contains","any":["scattered"]},{"type":"contains","any":["stacked"]},{"type":"contains","any":["confusion"]},{"type":"contains","any":["mess"]}]}},{"label":"Mentions the pressure of time","rule":{"type":"any","of":[{"type":"contains","any":["already"]},{"type":"contains","any":["arriv"]},{"type":"contains","any":["opening"]},{"type":"contains","any":["time"]},{"type":"contains","any":["people"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"The seeds had been stacked in the wrong sections and mixed together, and people were already beginning to arrive, so there was very little time to fix it."},{"kind":"write","sentence":7,"ask":"Why is Mrs. Navarro a significant character in the story?","checks":[{"label":"Says what she does","rule":{"type":"any","of":[{"type":"contains","any":["advice"]},{"type":"contains","any":["suggest"]},{"type":"contains","any":["tells"]},{"type":"contains","any":["helps"]},{"type":"contains","any":["calm"]},{"type":"contains","any":["one table"]}]}},{"label":"Says what it changes","rule":{"type":"any","of":[{"type":"contains","any":["kieran"]},{"type":"contains","any":["start"]},{"type":"contains","any":["sort"]},{"type":"contains","any":["step"]},{"type":"contains","any":["solve"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"She gives Kieran the advice to start with one table, which calms him down and shows him how to solve the problem step by step."},{"kind":"blank","sentence":8,"ask":"Which sentence marks the climax of the story?","answer":"Kieran took a deep breath and began sorting.","options":["Every spring, the town hosted a seed exchange.","Kieran took a deep breath and began sorting.","He spent weeks labeling envelopes, arranging tables, and creating signs."]},{"kind":"blank","sentence":10,"ask":"Which character trait best describes Kieran at the end of the story?","answer":"calm and composed","options":["calm and composed","careless and rushed","shy and quiet","competitive"]},{"kind":"write","sentence":10,"ask":"What does Kieran learn through his experience organizing the seed exchange?","checks":[{"label":"Mentions staying calm","rule":{"type":"any","of":[{"type":"contains","any":["calm"]},{"type":"contains","any":["deep breath"]},{"type":"contains","any":["panic"]}]}},{"label":"Mentions working through it","rule":{"type":"any","of":[{"type":"contains","any":["step"]},{"type":"contains","any":["one table"]},{"type":"contains","any":["at a time"]},{"type":"contains","any":["solve"]},{"type":"contains","any":["problem"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"Staying calm and solving problems step by step can help you overcome a challenge."}]},{"kind":"passage","brief":"A second passage.","sentences":["Nicole and her cousin Rowan spent a Saturday afternoon exploring a creek that flowed into the Redstone River.","The creek twisted through tall grasses and clusters of willow trees.","As they followed the water upstream, Rowan spotted an old metal marker attached to a fallen log.","Curious, they stepped off the path to investigate.","The marker was covered in dirt, but Nicole brushed it clean and revealed a faded arrow.","Wondering where it pointed, the cousins followed its direction along the creek bank.","After several minutes, they reached a narrow bend where Rowan noticed a small wooden box wedged between two rocks.","Inside was a weathered notebook filled with observations and sketches made by scientists who had studied the creek years earlier.","Excited by their discovery, Nicole and Rowan carefully returned the notebook to the box and reported it to the park ranger before heading home."],"hint":"The climax is the moment of the discovery, not what happens afterwards.","questions":[{"kind":"blank","sentence":3,"ask":"Why is the metal marker important to the plot of the story?","answer":"It helps the cousins find a notebook connected to the creek’s history.","options":["It shows that the cousins are experienced explorers.","It explains why scientists stopped studying the creek.","It helps the cousins find a notebook connected to the creek’s history.","It warns visitors about dangerous conditions near the river."]},{"kind":"blank","sentence":7,"ask":"Which sentence best shows the climax of the story?","answer":"Rowan noticed a small wooden box wedged between two rocks.","options":["The creek twisted through tall grasses and clusters of willow trees.","Rowan noticed a small wooden box wedged between two rocks.","They reported it to the park ranger before heading home."]},{"kind":"write","sentence":8,"ask":"Finish the sentence: finding the notebook is important to the plot because…","checks":[{"label":"Calls it the discovery","rule":{"type":"any","of":[{"type":"contains","any":["discover"]},{"type":"contains","any":["find"]},{"type":"contains","any":["found"]},{"type":"contains","any":["main"]}]}},{"label":"Connects it to the marker or the arrow","rule":{"type":"any","of":[{"type":"contains","any":["marker"]},{"type":"contains","any":["arrow"]},{"type":"contains","any":["follow"]},{"type":"contains","any":["point"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"it is the main discovery they make after following the arrow on the marker."},{"kind":"blank","sentence":9,"ask":"Which sentence shows the plot’s resolution?","answer":"They carefully returned the notebook to the box and reported it to the park ranger.","options":["They carefully returned the notebook to the box and reported it to the park ranger.","Rowan spotted an old metal marker attached to a fallen log.","Nicole brushed it clean and revealed a faded arrow."]}]},{"kind":"fix","mode":"drag","brief":"Put the right plot element in each blank.","bank":["rising action","resolution","climax","beginning"],"hint":"One of these four is not used.","items":[{"given":"____ builds suspense and leads up to the most exciting part of the story.","answer":"rising action"},{"given":"____ shows the solution to the problem and wraps up the story.","answer":"resolution"},{"given":"____ is the most important part of the story, where the most action takes place.","answer":"climax"}]}]},{"id":"at_rel","title":"Analyze Relationships","standards":["5.8B"],"skill":"What characters are to each other, and how the text shows it","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Evan enjoyed spending Saturdays in his grandfather’s workshop.","While others saw shelves of tools, Evan saw a place where he could learn valuable things from his grandfather.","He rarely explained every step.","Instead, he showed Evan how to begin and expected him to think through problems on his own.","One weekend, they worked together to build a shelf.","When Evan measured a board incorrectly, he became frustrated and wanted to start over.","His grandfather asked him to check his measurements again.","After looking carefully, Evan found his mistake and fixed it himself.","As they finished the project, Evan noticed his grandfather smiling quietly.","Evan felt proud because he knew he had solved the problem without giving up."],"hint":"What the grandfather does NOT do says as much as what he does.","questions":[{"kind":"blank","sentence":4,"ask":"What can be inferred about Evan’s grandfather?","answer":"He believes that solving problems helps people learn.","options":["He becomes frustrated when Evan makes mistakes.","He would rather build projects by himself than teach others.","He expects Evan to complete projects perfectly.","He believes that solving problems helps people learn."],"video":"at_rel-1"},{"kind":"blank","sentence":2,"ask":"Which sentence best shows that Evan respects his grandfather?","answer":"Evan saw a place where he could learn valuable things from his grandfather.","options":["Evan saw a place where he could learn valuable things from his grandfather.","When Evan measured a board incorrectly, he became frustrated.","One weekend, they worked together to build a shelf."],"video":"at_rel-2"}]},{"kind":"passage","brief":"A squirrel and a badger.","sentences":["Zibble the squirrel peered into the hollow log. “My acorn is gone!” he cried.","Mattias the badger sniffed the ground. “I’ll help you find it.”","They searched under ferns and behind rocks.","When Zibble tripped over a root, Mattias steadied him.","At last, they found the acorn near a berry bush.","“You always lose things,” Mattias teased.","Together, they carried the acorn home, laughing the whole way."],"hint":"Teasing that is followed by laughing is not the same as teasing that is not.","questions":[{"kind":"write","sentence":2,"ask":"What is the relationship between Zibble and Mattias?","checks":[{"label":"Names the relationship","rule":{"type":"any","of":[{"type":"contains","any":["friend"]},{"type":"contains","any":["close"]},{"type":"contains","any":["care"]}]}},{"label":"Points at something in the text","rule":{"type":"any","of":[{"type":"contains","any":["help"]},{"type":"contains","any":["steadied"]},{"type":"contains","any":["search"]},{"type":"contains","any":["laugh"]},{"type":"contains","any":["together"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"They are close friends, because Mattias helps Zibble look for the acorn and steadies him when he trips.","video":"at_rel-3"},{"kind":"blank","sentence":6,"ask":"What can the reader infer about the length of their relationship?","answer":"They know each other well and care about each other.","options":["They are still learning basic things about each other.","They know each other well and care about each other.","They rarely spend time together.","They only see each other during events."],"video":"at_rel-4"}]},{"kind":"passage","brief":"Three penguins on the ice.","sentences":["Milo, Tuck, and Poppy waddled across the ice toward a patch of fish.","“Last one there is a rotten fish,” Tuck called with a grin.","As they hurried along, Tuck shoved Poppy to the side.","She tripped and fell to the side, while Tuck hurried on ahead.","“Are you okay?” Milo asked, helping her to her feet.","Later, when the wind picked up, Milo guided Poppy behind a ridge for shelter.","Tuck arrived a moment later. “Good spot,” he said, settling in beside them."],"hint":"One of them stops. One of them keeps going.","questions":[{"kind":"blank","sentence":5,"ask":"Who is a better friend to Poppy?","answer":"Milo","options":["Milo","Tuck"],"video":"at_rel-5"},{"kind":"write","sentence":5,"ask":"What does the relationship between Poppy and Milo show about Milo?","checks":[{"label":"Names a trait","rule":{"type":"any","of":[{"type":"contains","any":["kind"]},{"type":"contains","any":["caring"]},{"type":"contains","any":["thoughtful"]},{"type":"contains","any":["helpful"]},{"type":"contains","any":["looks out"]},{"type":"contains","any":["considerate"]}]}},{"label":"Points at what he did","rule":{"type":"any","of":[{"type":"contains","any":["help"]},{"type":"contains","any":["feet"]},{"type":"contains","any":["shelter"]},{"type":"contains","any":["ridge"]},{"type":"contains","any":["guided"]},{"type":"contains","any":["asked"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"It shows Milo is kind and caring, because he stops to help Poppy up and later guides her to shelter.","video":"at_rel-6"},{"kind":"blank","sentence":3,"ask":"Which conclusion can be made about the three penguins’ relationships?","answer":"Milo and Poppy seem to trust one another, while Tuck is more competitive.","options":["Milo and Poppy seem to trust one another, while Tuck is more competitive.","Tuck and Poppy are close friends because they spend the most time together.","Milo prefers to travel alone and does not want to spend time with either penguin.","All three penguins treat one another in exactly the same way."],"video":"at_rel-7"}]},{"kind":"passage","brief":"One more.","sentences":["Macy, her younger brother Ron, and their dad spent the afternoon cleaning the yard.","When a strong gust of wind scattered Ron’s pile of leaves, he groaned in frustration.","“Need a hand?” Macy asked.","Their dad handed Ron a rake and said, “Challenges are easier when we work together.”","Macy helped Ron gather the leaves again, and before long, the yard looked neat and tidy."],"hint":"Look for the moment someone offers something without being asked.","questions":[{"kind":"blank","sentence":3,"ask":"Which sentence shows how Macy and Ron support each other?","answer":"“Need a hand?” Macy asked.","options":["“Need a hand?” Macy asked.","A strong gust of wind scattered Ron’s pile of leaves.","The yard looked neat and tidy."],"video":"at_rel-8"},{"kind":"write","sentence":5,"ask":"How would you describe the relationship Macy has with her family?","checks":[{"label":"Names the relationship","rule":{"type":"any","of":[{"type":"contains","any":["support"]},{"type":"contains","any":["help"]},{"type":"contains","any":["close"]},{"type":"contains","any":["caring"]},{"type":"contains","any":["together"]}]}},{"label":"Points at the text","rule":{"type":"any","of":[{"type":"contains","any":["leaves"]},{"type":"contains","any":["rake"]},{"type":"contains","any":["hand"]},{"type":"contains","any":["yard"]},{"type":"contains","any":["ron"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"They are a supportive family who help each other, because Macy offers Ron a hand and they gather the leaves together.","video":"at_rel-9"}]}]}],"skillBuilders":{"at_setting":{"id":"at_sb_setting","title":"SB: Setting","standards":["5.8D"],"skill":"Finding where and when, one story at a time","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["In 1915, Elena lived in a small village high in the Andes Mountains of Peru.","Because the steep mountain roads were difficult to travel, nearby communities often depended on messengers to deliver important news and supplies.","Each spring, villagers celebrated the Festival of the Condor, a community event that included traditional music, woven textiles, and dances honoring the region’s history.","The day before the festival, Elena’s grandfather asked her to carry a bundle of decorated ribbons to a neighboring village.","The ribbons were needed for a ceremonial display at the celebration.","As Elena followed the narrow mountain path, dark clouds rolled over the peaks and a heavy rainstorm began.","The rocky trail became slippery, and a fast-moving stream blocked her usual route.","Remembering a safer path used by local shepherds, Elena carefully crossed the hillside and reached the village before sunset.","The next day, the ribbons were displayed at the festival, and Elena felt proud that she had helped continue an important community tradition."],"hint":"Sentence 1 gives you both halves of the setting at once.","questions":[{"kind":"blank","sentence":1,"ask":"Where and when is the story set?","answer":"the Andes Mountains of Peru, in 1915","options":["the Andes Mountains of Peru, in 1915","the Sahara Desert in Morocco, hundreds of years ago","a historic town in Vietnam, in 2008"],"video":"at_sb_setting-1"},{"kind":"blank","sentence":6,"ask":"Which detail from the setting creates a challenge for Elena?","answer":"the rainstorm","options":["the rainstorm","the ribbons","the festival","the shepherds"],"video":"at_sb_setting-2"},{"kind":"write","sentence":3,"ask":"Give one example of a cultural detail from the story.","checks":[{"label":"Names something cultural","rule":{"type":"any","of":[{"type":"contains","any":["festival"]},{"type":"contains","any":["condor"]},{"type":"contains","any":["music"]},{"type":"contains","any":["textile"]},{"type":"contains","any":["dance"]},{"type":"contains","any":["tradition"]},{"type":"contains","any":["ceremon"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":5}}],"model":"The Festival of the Condor included traditional music, woven textiles, and dances honouring the region’s history.","video":"at_sb_setting-3"}]},{"kind":"passage","brief":"A second passage.","sentences":["Hundreds of years ago in Morocco, a girl named Samira lived near the edge of the Sahara Desert.","Every autumn, families from nearby villages gathered for a trading festival.","Merchants filled the marketplace with woven rugs, colorful pottery, dried fruits, and carved wooden tools.","In the center of the square stood a large water fountain where travelers rested after long journeys across the desert.","On the morning of the festival, Samira noticed that the fountain had stopped flowing.","Without water, many travelers would have nowhere to refill their supplies before continuing their trips.","Village leaders worried that visitors might leave early and miss the celebration.","Samira remembered hearing her grandfather explain how water reached the fountain through a narrow underground channel.","Following the channel’s path, she discovered that shifting sand from a recent windstorm had blocked part of the system.","After several villagers worked together to clear the blockage, water began flowing again.","By midday, travelers gathered around the fountain, and the festival continued as planned."],"hint":"A unique feature of a setting is something this place has that another would not.","questions":[{"kind":"blank","sentence":2,"ask":"Which detail shows a cultural element of the setting?","answer":"Families gathered for a trading festival each autumn.","options":["A windstorm moved sand across the desert.","Families gathered for a trading festival each autumn.","Samira followed the underground channel."],"video":"at_sb_setting-4"},{"kind":"blank","sentence":1,"ask":"Where does the story take place?","answer":"Morocco, near the edge of the Sahara Desert","options":["Morocco, near the edge of the Sahara Desert","Peru, high in the Andes Mountains","Vietnam, in a historic riverside town"],"video":"at_sb_setting-5"},{"kind":"blank","sentence":9,"ask":"How does the setting create problems for the story?","answer":"Shifting sand blocks the water system that serves the festival.","options":["Desert animals scare visitors away from the festival.","Travelers become lost while crossing the marketplace.","Shifting sand blocks the water system that serves the festival."],"video":"at_sb_setting-6"},{"kind":"write","sentence":8,"ask":"What is one unique feature of this setting that affects the plot and characters?","checks":[{"label":"Names the feature","rule":{"type":"any","of":[{"type":"contains","any":["water"]},{"type":"contains","any":["fountain"]},{"type":"contains","any":["channel"]},{"type":"contains","any":["underground"]}]}},{"label":"Says what it does to the story","rule":{"type":"any","of":[{"type":"contains","any":["festival"]},{"type":"contains","any":["travel"]},{"type":"contains","any":["block"]},{"type":"contains","any":["sand"]},{"type":"contains","any":["depend"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"The village depends on an underground water channel in the desert, so when sand blocks it the festival is affected.","video":"at_sb_setting-7"}]}]},"at_plot":{"id":"at_sb_plot","title":"SB: Plot Elements","standards":["5.8C"],"skill":"Naming the parts of a story, then finding them","activities":[{"kind":"fix","mode":"drag","bank":["rising action","climax","resolution","beginning"],"brief":"Which plot element does each sentence describe?","hint":"All four are used this time.","items":[{"given":"The ____ builds suspense and leads up to the most exciting part of the story.","answer":"rising action","video":"at_sb_plot-1"},{"given":"The ____ is the most important part of the story, where the most action takes place.","answer":"climax","video":"at_sb_plot-2"},{"given":"The ____ shows the solution to the problem and wraps up the story.","answer":"resolution","video":"at_sb_plot-3"},{"given":"The ____ establishes the setting, key characters, and what normal life looks like.","answer":"beginning","video":"at_sb_plot-4"}]},{"kind":"passage","brief":"Read the passage, then answer.","sentences":["Luna, a curious Arctic fox, explored the winding streets of a new town.","At dusk, she followed a trail that led into a wooded park.","As darkness settled, she realized she could no longer see the path back to town.","Her heart raced as unfamiliar sounds echoed through the trees.","Instead of panicking, Luna stopped, studied a park map, and followed the trail to safety."],"hint":"Getting lost is the problem. What does the problem make happen?","questions":[{"kind":"write","sentence":3,"ask":"How does Luna getting lost advance the plot?","checks":[{"label":"Names the problem","rule":{"type":"any","of":[{"type":"contains","any":["lost"]},{"type":"contains","any":["path"]},{"type":"contains","any":["dark"]},{"type":"contains","any":["cannot see"]},{"type":"contains","any":["could not see"]}]}},{"label":"Says what it causes","rule":{"type":"any","of":[{"type":"contains","any":["map"]},{"type":"contains","any":["solve"]},{"type":"contains","any":["safety"]},{"type":"contains","any":["calm"]},{"type":"contains","any":["stop"]},{"type":"contains","any":["find"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"Getting lost is the problem that makes Luna stop, study the park map, and find her own way back to safety.","video":"at_sb_plot-5"},{"kind":"write","sentence":5,"ask":"Finish the statement: by the end of the story, Luna has learned to…","checks":[{"label":"Mentions staying calm","rule":{"type":"any","of":[{"type":"contains","any":["calm"]},{"type":"contains","any":["not panic"]},{"type":"contains","any":["panic"]},{"type":"contains","any":["stop"]}]}},{"label":"Mentions solving it","rule":{"type":"any","of":[{"type":"contains","any":["think"]},{"type":"contains","any":["map"]},{"type":"contains","any":["solve"]},{"type":"contains","any":["problem"]},{"type":"contains","any":["work out"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"stay calm instead of panicking, and think a problem through until she solves it.","video":"at_sb_plot-6"}]},{"kind":"fix","mode":"select","bank":[],"brief":"Put these events in the order they happen. The last one is done for you.","hint":"Read them as a story, from the ordinary morning to the award.","items":[{"given":"First  →  ____","answer":"Lorelei was excited to inspect the newly built mountain bridge.","options":["Lorelei was excited to inspect the newly built mountain bridge.","A support cable snapped and sent debris toward the hikers.","Lorelei activated the emergency barrier and redirected the rocks.","The hikers applauded as the trail reopened."],"video":"at_sb_plot-7"},{"given":"Second  →  ____","answer":"A support cable snapped and sent debris toward the hikers.","options":["Lorelei was excited to inspect the newly built mountain bridge.","A support cable snapped and sent debris toward the hikers.","Lorelei activated the emergency barrier and redirected the rocks.","The hikers applauded as the trail reopened."]},{"given":"Third  →  ____","answer":"Lorelei activated the emergency barrier and redirected the rocks.","options":["Lorelei was excited to inspect the newly built mountain bridge.","A support cable snapped and sent debris toward the hikers.","Lorelei activated the emergency barrier and redirected the rocks.","The hikers applauded as the trail reopened."]},{"given":"Fourth  →  ____","answer":"The hikers applauded as the trail reopened.","options":["Lorelei was excited to inspect the newly built mountain bridge.","A support cable snapped and sent debris toward the hikers.","Lorelei activated the emergency barrier and redirected the rocks.","The hikers applauded as the trail reopened."]}]},{"kind":"passage","brief":"One more passage.","sentences":["Mina the Margay was a student researcher at the Northern Science Center.","She loved solving problems and collecting information about local wildlife.","One afternoon, her team prepared to present the results of an important migration study.","However, just before the presentation, Mina discovered that the digital file containing months of survey data had disappeared.","Without the information, the team could not share its findings with the community.","The researchers searched every computer and storage device, but the file remained missing.","Then Mina remembered seeing a backup drive connected to a field tablet during a recent expedition.","She hurried to the equipment room and found the tablet charging on a shelf.","After opening the backup folder, she located the missing data and transferred it to the presentation computer.","The team successfully shared its research that evening, and the community gained valuable information about protecting local wildlife."],"hint":"The climax is the moment the problem turns, not the moment it starts.","questions":[{"kind":"blank","sentence":9,"ask":"Which sentence best describes the climax of the story?","answer":"She located the missing data and transferred it to the presentation computer.","options":["She located the missing data and transferred it to the presentation computer.","Mina was a student researcher at the Northern Science Center.","The researchers searched every computer and storage device."],"video":"at_sb_plot-11"},{"kind":"blank","sentence":1,"ask":"Which sentence best describes the beginning of the story?","answer":"Mina the Margay was a student researcher at the Northern Science Center.","options":["Mina the Margay was a student researcher at the Northern Science Center.","The digital file containing months of survey data had disappeared.","The team successfully shared its research that evening."],"video":"at_sb_plot-12"},{"kind":"write","sentence":7,"ask":"Why is the backup drive significant to the story?","checks":[{"label":"Says what it holds or does","rule":{"type":"any","of":[{"type":"contains","any":["data"]},{"type":"contains","any":["file"]},{"type":"contains","any":["copy"]},{"type":"contains","any":["information"]}]}},{"label":"Says what it lets them do","rule":{"type":"any","of":[{"type":"contains","any":["present"]},{"type":"contains","any":["share"]},{"type":"contains","any":["solve"]},{"type":"contains","any":["find"]},{"type":"contains","any":["research"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"The backup drive holds a copy of the missing data, which is what lets Mina solve the problem and the team share its research.","video":"at_sb_plot-13"}]}]},"at_rel":{"id":"at_sb_rel","title":"SB: Analyze Relationships","standards":["5.8B"],"skill":"Friends, rivals, enemies — and how to tell which","activities":[{"kind":"fix","mode":"select","bank":[],"brief":"Read each passage. What relationship does it describe?","hint":"Friends care about each other. Rivals compete. Enemies may try to hurt each other.","items":[{"given":"Cam slid his notebook across the table so Elle could compare her calculations. Later, they revised their presentation together, exchanging suggestions and laughing about the experiment.  →  ____","answer":"friends","options":["friends","rivals","enemies"],"video":"at_sb_rel-1"},{"given":"The fox froze when it noticed the hawk tracing wide circles overhead. It searched for cover while the hawk continued scanning the hillside, waiting for an opportunity to strike.  →  ____","answer":"enemies","options":["friends","rivals","enemies"],"video":"at_sb_rel-2"},{"given":"Jeff checked the scoreboard before turning toward Harper. He knew she was studying it just as carefully so she could find a way to beat him next time.  →  ____","answer":"rivals","options":["friends","rivals","enemies"],"video":"at_sb_rel-3"}]},{"kind":"passage","brief":"Read the passage, then answer.","sentences":["Zuri and Callan were both running for class president.","During lunch, they handed out campaign flyers and explained their ideas to classmates.","When Callan’s poster accidentally tore, Zuri lent him some tape so he could fix it.","Later, Callan congratulated Zuri after her speech earned loud applause.","On election day, they eagerly awaited the results.","Although each hoped to win, both respected the effort and leadership skills the other had shown throughout the campaign."],"hint":"They want the same job. Watch how they treat each other anyway.","questions":[{"kind":"write","sentence":6,"ask":"Finish the sentence: Zuri and Callan show that competitors can also be…","checks":[{"label":"Names what they also are","rule":{"type":"any","of":[{"type":"contains","any":["friend"]},{"type":"contains","any":["kind"]},{"type":"contains","any":["respect"]},{"type":"contains","any":["support"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":4}}],"model":"friendly and respectful towards each other, even while they are both trying to win.","video":"at_sb_rel-4"},{"kind":"write","sentence":4,"ask":"How does Callan show care for Zuri?","checks":[{"label":"Names what he did","rule":{"type":"any","of":[{"type":"contains","any":["congratulat"]},{"type":"contains","any":["speech"]},{"type":"contains","any":["applause"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":5}}],"model":"He congratulated Zuri after her speech earned loud applause, even though she was his opponent.","video":"at_sb_rel-5"},{"kind":"blank","sentence":6,"ask":"Which sentence best describes Zuri and Callan’s relationship?","answer":"Zuri and Callan are friendly rivals competing for the position of class president.","options":["Zuri and Callan are classmates who work together to improve their school.","Zuri and Callan are opponents who refuse to support one another during the election.","Zuri and Callan are friendly rivals competing for the position of class president."],"video":"at_sb_rel-6"}]},{"kind":"passage","brief":"One more.","sentences":["Aiko and Keiko spent the afternoon repairing kites before the town’s annual kite festival.","When a bamboo support snapped on Aiko’s kite, Keiko showed her how to replace it without damaging the paper.","Later, Aiko noticed that one of Keiko’s kites had a loose string and quickly fixed it.","As colorful kites filled the sky the next morning, they smiled, glad their hard work had paid off."],"hint":"Help going both ways is the thing to look for.","questions":[{"kind":"blank","sentence":2,"ask":"Which sentence shows Aiko and Keiko helping one another?","answer":"Keiko showed her how to replace it without damaging the paper.","options":["Keiko showed her how to replace it without damaging the paper.","Colorful kites filled the sky the next morning.","They spent the afternoon repairing kites before the festival."],"video":"at_sb_rel-7"},{"kind":"blank","sentence":4,"ask":"How would you describe the relationship between Aiko and Keiko?","answer":"Aiko and Keiko are friends who support each other.","options":["Aiko and Keiko are friends who support each other.","Aiko and Keiko are competitors who each want their own kite to be more successful.","Aiko and Keiko are neighbors who rarely spend time together."],"video":"at_sb_rel-8"}]}]}},"full":{"id":"at_full","title":"Full Topic: Analyze a Text","standards":["5.8B","5.8C","5.8D"],"skill":"Relationships, plot and setting, in one piece of writing","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Mara spent Saturday morning helping her aunt build a small birdhouse for the garden.","Her aunt showed her how to read the instructions and use the measuring tape, but Mara completed most of the work herself.","Everything was going well until she attached the roof.","One side stuck up higher than the other, making the birdhouse wobble.","Mara felt disappointed and thought about starting over.","Instead, she carefully looked at each step and compared her work to the directions.","After checking her measurements, she discovered that one piece had been placed upside down.","Mara removed the piece, fixed the mistake, and attached the roof again.","This time the birdhouse stood straight and sturdy.","Mara felt proud because she had solved the problem by being patient and paying close attention to the details."],"hint":"She thought about starting over — and then did something else instead.","questions":[{"kind":"blank","sentence":8,"ask":"Which character trait does Mara demonstrate most clearly?","answer":"Mara shows determination by fixing her mistake.","options":["Mara shows impatience by rushing her work.","Mara shows determination by fixing her mistake.","Mara shows curiosity by asking many questions.","Mara shows generosity by helping others."],"video":"at_full-1"},{"kind":"blank","sentence":1,"ask":"Which sentence describes the setting?","answer":"Mara spent Saturday morning helping her aunt build a small birdhouse for the garden.","options":["Mara spent Saturday morning helping her aunt build a small birdhouse for the garden.","One side stuck up higher than the other, making the birdhouse wobble.","Mara felt proud because she had solved the problem."],"video":"at_full-2"}]},{"kind":"passage","brief":"A second passage.","sentences":["Aaron and his sister Allie hiked along an overgrown trail behind their grandfather’s farm.","They were searching for a landmark mentioned in his old journal.","As the path became harder to follow, they worried they had taken a wrong turn.","Then Allie spotted a weathered stone marker hidden by tall grass.","Nearby, they uncovered a small notebook filled with sketches and observations about the area’s wildlife."],"hint":"Tension is the worry before the discovery.","questions":[{"kind":"write","sentence":3,"ask":"How does the author create tension before the notebook is discovered?","checks":[{"label":"Names the worry","rule":{"type":"any","of":[{"type":"contains","any":["worr"]},{"type":"contains","any":["wrong turn"]},{"type":"contains","any":["lost"]},{"type":"contains","any":["harder"]}]}},{"label":"Names the trail","rule":{"type":"any","of":[{"type":"contains","any":["path"]},{"type":"contains","any":["trail"]},{"type":"contains","any":["follow"]},{"type":"contains","any":["overgrown"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"The author creates tension by showing that Aaron and Allie are worried they took a wrong turn when the path becomes harder to follow.","video":"at_full-3"},{"kind":"blank","sentence":5,"ask":"Why is the notebook important to the plot of the story?","answer":"It helps Aaron and Allie learn more about the area’s wildlife.","options":["It proves that Aaron and Allie followed the wrong trail.","It explains why the farm was abandoned.","It warns visitors about dangerous animals.","It helps Aaron and Allie learn more about the area’s wildlife."],"video":"at_full-4"}]},{"kind":"passage","brief":"A last passage.","sentences":["During a weekend visit to their grandpa’s remote cabin, Elena and her younger brother, Marcus, uncovered a weathered journal hidden beneath a loose floorboard.","Intrigued by its mysterious entries, the siblings deciphered clues that described landmarks scattered throughout the surrounding forest.","They located a long-abandoned lookout tower, where they were able to take a photo with Elena’s phone.","At the top, they secretly thanked their grandpa for showing them his home."],"hint":"One object in sentence 3 tells you the century.","questions":[{"kind":"pick","sentence":3,"ask":"Click the word in sentence 3 that tells you the time period, then write which century it makes this.","target":"phone","answer":"twenty-first","video":"at_full-5"},{"kind":"write","sentence":2,"ask":"What characteristic do Elena and Marcus share?","checks":[{"label":"Names the trait","rule":{"type":"any","of":[{"type":"contains","any":["curious"]},{"type":"contains","any":["curiosity"]},{"type":"contains","any":["intrigued"]},{"type":"contains","any":["interested"]}]}},{"label":"Points at the text","rule":{"type":"any","of":[{"type":"contains","any":["journal"]},{"type":"contains","any":["clue"]},{"type":"contains","any":["mystery"]},{"type":"contains","any":["mysterious"]},{"type":"contains","any":["learn"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"Elena and Marcus are both curious, because they want to learn more about the mysterious journal and its clues.","video":"at_full-6"},{"kind":"blank","sentence":3,"ask":"What detail starts the resolution of the story?","answer":"The resolution begins when Elena and Marcus locate the abandoned lookout tower.","options":["The resolution begins when Elena and Marcus locate the abandoned lookout tower.","The resolution begins when the siblings uncover the journal.","The resolution begins when they decipher the clues.","The resolution begins when they begin searching for answers."],"video":"at_full-7"},{"kind":"write","sentence":4,"ask":"How does the journal impact the relationship between the siblings and their grandpa?","checks":[{"label":"Says what it does for them","rule":{"type":"any","of":[{"type":"contains","any":["closer"]},{"type":"contains","any":["thank"]},{"type":"contains","any":["connect"]},{"type":"contains","any":["understand"]},{"type":"contains","any":["learn"]},{"type":"contains","any":["share"]}]}},{"label":"Mentions grandpa or his home","rule":{"type":"any","of":[{"type":"contains","any":["grandpa"]},{"type":"contains","any":["home"]},{"type":"contains","any":["cabin"]},{"type":"contains","any":["his"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"The journal brings them closer to their grandpa, because it shows them his home and they end up secretly thanking him for it.","video":"at_full-8"}]},{"kind":"fix","mode":"drag","bank":["rising action","resolution","climax","beginning"],"brief":"Put the right plot element in each blank.","hint":"One of these four is not used.","items":[{"given":"____ builds suspense and leads up to the most exciting part of the story.","answer":"rising action","video":"at_full-9"},{"given":"____ shows the solution to the problem and wraps up the story.","answer":"resolution","video":"at_full-9"},{"given":"____ is the most important part of the story, where the most action takes place.","answer":"climax","video":"at_full-9"}]}]}},{"id":"topic_argumentative","title":"Argumentative Texts","short":"Argumentative Texts","state":"TX","grade":5,"domain":"Multiple Genres","standards":["5.9E (i)","5.9E (ii)","5.9E (iii)"],"blurb":"Claim, evidence and audience — three skills, then one full-topic proof.","icon":"⚖️","core":[{"id":"arg_claim","title":"Identify the Claim","standards":["5.9E (i)"],"skill":"Finding the sentence the whole text is trying to make you agree with","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Many schools should schedule outdoor learning days several times each year.","Learning outside can help students stay focused and engaged during lessons.","Science activities become more meaningful when students can observe plants, animals, and weather conditions firsthand.","Outdoor learning also encourages movement, which can improve attention and reduce stress.","Students often have opportunities to work together on hands-on projects while exploring their surroundings.","Some people worry that students may become distracted outside.","However, teachers can plan structured activities that keep students focused on learning.","For these reasons, schools should include outdoor learning days as part of the school year."],"hint":"The claim is usually the first or last sentence, and it says what SHOULD happen.","questions":[{"kind":"blank","sentence":1,"ask":"Which sentence best states the author’s claim?","answer":"Many schools should schedule outdoor learning days several times each year.","options":["Many schools should schedule outdoor learning days several times each year.","Some people worry that students may become distracted outside.","Outdoor learning also encourages movement, which can improve attention and reduce stress."],"video":"arg_claim-1"},{"kind":"blank","sentence":3,"ask":"Which detail supports the claim?","answer":"Science activities become more meaningful when students can observe plants, animals, and weather conditions firsthand.","options":["Science activities become more meaningful when students can observe plants, animals, and weather conditions firsthand.","Some people worry that students may become distracted outside.","Many schools should schedule outdoor learning days several times each year."],"video":"arg_claim-2"},{"kind":"write","sentence":8,"ask":"In your own words, what is the main claim the author makes?","checks":[{"label":"Names outdoor learning","rule":{"type":"any","of":[{"type":"contains","any":["outdoor"]},{"type":"contains","any":["outside"]}]}},{"label":"Says schools should do it","rule":{"type":"any","of":[{"type":"contains","any":["should"]},{"type":"contains","any":["ought"]},{"type":"contains","any":["need to"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"The author claims that schools should schedule outdoor learning days as part of the school year.","video":"arg_claim-3"}]},{"kind":"passage","brief":"A second argument.","sentences":["Communities should build more skate parks for children and teens.","Skate parks provide a safe place for people to practice skateboarding, roller skating, and other activities.","When riders have a designated area to use, they are less likely to skate in parking lots or busy streets.","Skate parks can also encourage exercise and help people spend more time outdoors.","Some residents worry that skate parks might create noise in nearby neighborhoods.","However, communities can choose locations that reduce disruptions while still giving young people a place to gather.","For these reasons, communities should invest in more skate parks."],"hint":"An opposing claim is the one the author disagrees with.","questions":[{"kind":"blank","sentence":2,"ask":"Which sentence supports the author’s claim?","answer":"Skate parks provide a safe place for people to practice skateboarding, roller skating, and other activities.","options":["Skate parks provide a safe place for people to practice skateboarding, roller skating, and other activities.","Some residents worry that skate parks might create noise in nearby neighborhoods.","Communities should build more skate parks for children and teens."],"video":"arg_claim-4"},{"kind":"blank","sentence":5,"ask":"Which sentence presents an opposing claim?","answer":"Some residents worry that skate parks might create noise in nearby neighborhoods.","options":["Some residents worry that skate parks might create noise in nearby neighborhoods.","Skate parks can also encourage exercise and help people spend more time outdoors.","For these reasons, communities should invest in more skate parks."],"video":"arg_claim-5"}]},{"kind":"passage","brief":"A third argument.","sentences":["Students should learn basic cooking skills before they enter middle school.","Learning how to prepare simple meals can help children become more independent and responsible.","Cooking also teaches important skills such as following directions, measuring ingredients, and managing time.","Many children enjoy helping in the kitchen and trying new foods.","These experiences can build confidence and encourage healthy eating habits.","Basic cooking skills may also help families save money by preparing meals at home.","Some people believe cooking should only be taught by family members.","Even so, many adults agree that cooking is an important life skill that benefits children in many ways.","For these reasons, students should learn basic cooking skills at a young age."],"hint":"Two sentences support the claim. One argues against it.","questions":[{"kind":"blank","sentence":2,"ask":"Which sentence supports the author’s claim?","answer":"Learning how to prepare simple meals can help children become more independent and responsible.","options":["Learning how to prepare simple meals can help children become more independent and responsible.","Some people believe cooking should only be taught by family members.","Many children enjoy helping in the kitchen and trying new foods."],"video":"arg_claim-6"},{"kind":"blank","sentence":7,"ask":"Which sentence presents an opposing claim?","answer":"Some people believe cooking should only be taught by family members.","options":["Some people believe cooking should only be taught by family members.","Cooking also teaches important skills such as following directions, measuring ingredients, and managing time.","Basic cooking skills may also help families save money by preparing meals at home."],"video":"arg_claim-7"},{"kind":"blank","sentence":1,"ask":"What is one claim the author makes in the selection?","answer":"Students should learn basic cooking skills before they enter middle school.","options":["Learning how to prepare simple meals can help children become more independent and responsible.","Some people believe cooking should only be taught by family members.","Students should learn basic cooking skills before they enter middle school.","Basic cooking skills may also help families save money by preparing meals at home."],"video":"arg_claim-8"}]},{"kind":"passage","brief":"One more.","sentences":["Free outdoor movie nights can be a valuable addition to community events.","Supporters argue that these events bring neighbors together in a fun and welcoming setting.","Families can enjoy entertainment without spending money on expensive tickets.","Outdoor movie nights also encourage residents to spend time in local parks and public spaces.","Some people think communities should spend money on other activities instead.","However, many residents believe movie nights help strengthen community connections while providing affordable entertainment."],"hint":"Work backwards: what claim would this sentence be a reason FOR?","questions":[{"kind":"blank","sentence":3,"ask":"Which claim does this sentence support? “Families can enjoy entertainment without spending money on expensive tickets.”","answer":"Free outdoor movie nights can be a valuable addition to community events.","options":["Free outdoor movie nights can be a valuable addition to community events.","Some people think communities should spend money on other activities instead.","Outdoor movie nights also encourage residents to spend time in local parks."],"video":"arg_claim-9"}]}]},{"id":"arg_audience","title":"The Audience","standards":["5.9E (iii)"],"skill":"Working out who the author is actually talking to","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Schools are considering adding more hands-on science activities to their classrooms.","Experiments and investigations allow students to apply concepts they learn from textbooks.","Research suggests that active participation can improve understanding and retention of information.","These activities also encourage collaboration and problem-solving skills.","Although additional materials may be required, the educational benefits can outweigh the costs.","School administrators should consider expanding opportunities for hands-on learning."],"hint":"The last sentence usually names who is being asked to act.","questions":[{"kind":"write","sentence":6,"ask":"Who is the author most likely addressing?","checks":[{"label":"Names the audience","rule":{"type":"any","of":[{"type":"contains","any":["administrator"]},{"type":"contains","any":["principal"]},{"type":"contains","any":["school leader"]},{"type":"contains","any":["leaders"]},{"type":"contains","any":["teachers"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":4}}],"model":"The author is addressing school administrators, who are asked to expand hands-on learning.","video":"arg_audience-1"},{"kind":"blank","sentence":6,"ask":"Which reader would most likely agree with the author’s argument?","answer":"A principal looking for ways to improve instruction","options":["A principal looking for ways to improve instruction","A scientist conducting research in a laboratory","A student studying for a college entrance exam"],"video":"arg_audience-2"}]},{"kind":"passage","brief":"A second argument.","sentences":["Many neighborhoods would benefit from establishing a community farmers market.","Farmers markets provide residents with access to fresh fruits, vegetables, and other locally produced goods.","Purchasing food from local growers can support small businesses and strengthen the local economy.","These markets also create opportunities for community members to gather and learn about healthy food choices.","Although organizing a market requires planning and coordination, the long-term benefits can positively affect many residents.","Community leaders should consider supporting this initiative."],"hint":"Who is being asked to do something here?","questions":[{"kind":"blank","sentence":3,"ask":"Which detail would most interest the intended audience?","answer":"Purchasing food from local growers can support small businesses and strengthen the local economy.","options":["Purchasing food from local growers can support small businesses and strengthen the local economy.","Organizing a market requires planning and coordination.","Farmers markets provide residents with fresh fruits and vegetables."],"video":"arg_audience-3"},{"kind":"write","sentence":6,"ask":"Who would most likely support this idea?","checks":[{"label":"Names the audience","rule":{"type":"any","of":[{"type":"contains","any":["community leader"]},{"type":"contains","any":["leaders"]},{"type":"contains","any":["council"]},{"type":"contains","any":["resident"]},{"type":"contains","any":["official"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":4}}],"model":"Community leaders would most likely support it, because they are the ones asked to back the initiative.","video":"arg_audience-4"}]},{"kind":"passage","brief":"A third argument.","sentences":["Many families should consider adopting pets from local animal shelters.","Shelters care for animals that need safe and permanent homes.","Adopting a pet can provide companionship while also giving an animal a second chance.","Many shelters offer information about pet care and help families find animals that fit their lifestyles.","Although adopting a pet requires responsibility and commitment, the rewards can be meaningful for both families and animals.","People looking for a pet should visit their local shelter before purchasing one elsewhere."],"hint":"Look at who the text keeps mentioning.","questions":[{"kind":"write","sentence":1,"ask":"Who is most likely the intended audience of this passage?","checks":[{"label":"Names the audience","rule":{"type":"any","of":[{"type":"contains","any":["famil"]},{"type":"contains","any":["people looking"]},{"type":"contains","any":["pet owner"]},{"type":"contains","any":["adopt"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":4}}],"model":"The intended audience is families who are thinking about getting a pet.","video":"arg_audience-5"},{"kind":"blank","sentence":1,"ask":"Which reader would most likely agree with the author’s argument?","answer":"A family deciding whether to adopt a pet","options":["A family deciding whether to adopt a pet","A veterinarian performing surgery on animals","A scientist studying animal behavior","A zookeeper caring for exotic animals"],"video":"arg_audience-6"},{"kind":"blank","sentence":4,"ask":"Which detail would most interest the intended audience?","answer":"Many shelters offer information about pet care and help families find animals that fit their lifestyles.","options":["Shelters provide safe homes for animals while they await adoption.","Many shelters offer information about pet care and help families find animals that fit their lifestyles.","Adopting a pet requires time, effort, and daily responsibility.","Pets often provide companionship and comfort for their owners."],"video":"arg_audience-7"}]},{"kind":"passage","brief":"One more.","sentences":["More students should join school chess clubs.","Playing chess requires strategic thinking and careful decision-making.","Students who participate often strengthen their problem-solving abilities while learning from both victories and mistakes.","Students should consider joining a chess club if one is available."],"hint":"Short text, but it says who it is for twice.","questions":[{"kind":"write","sentence":4,"ask":"Who is most likely the intended audience of this text?","checks":[{"label":"Names students","rule":{"type":"contains","any":["student"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":4}}],"model":"The intended audience is students who might join a school chess club.","video":"arg_audience-8"}]}]},{"id":"arg_facts","title":"For or Against an Argument","standards":["5.9E (ii)"],"skill":"Spotting the facts an author uses, and what each one is doing","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Community centers should offer more esports tournaments for students.","Esports are video game competitions where players work together as a team.","These games help students practice teamwork and quick thinking.","According to a survey by several youth programs, more students joined community activities after esports events were added.","Some people believe community centers should focus only on traditional sports.","However, many organizers say esports give students another fun way to stay active and involved.","For these reasons, community centers should offer more esports tournaments."],"hint":"A fact usually says where it came from — a survey, a study, records.","questions":[{"kind":"blank","sentence":4,"ask":"Which sentence uses a fact to support the claim about esports?","answer":"According to a survey by several youth programs, more students joined community activities after esports events were added.","options":["According to a survey by several youth programs, more students joined community activities after esports events were added.","Esports are video game competitions where players work together as a team.","Some people believe community centers should focus only on traditional sports."],"video":"arg_facts-1"},{"kind":"write","sentence":6,"ask":"“Some people believe community centers should focus only on traditional sports.” How does the author argue against this idea?","checks":[{"label":"Points at the answer sentence","rule":{"type":"any","of":[{"type":"contains","any":["organizer"]},{"type":"contains","any":["another"]},{"type":"contains","any":["active"]},{"type":"contains","any":["involved"]},{"type":"contains","any":["fun"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"The author answers it by saying many organizers think esports give students another fun way to stay active and involved.","video":"arg_facts-2"}]},{"kind":"passage","brief":"A second argument.","sentences":["Public libraries should offer more hands-on workshops for children.","In these workshops, kids can learn skills like coding, building, and art.","Library attendance records from several cities show that more people visit when workshops are offered often.","Workshops also help children discover new interests and solve problems in creative ways.","Some people believe libraries should focus only on books and reading.","However, many communities have found that workshops bring in more visitors while helping kids learn outside the classroom.","For these reasons, libraries should offer more workshops for children."],"hint":"Attendance records are evidence. Ask what they are evidence OF.","questions":[{"kind":"blank","sentence":3,"ask":"Which sentence provides factual evidence that workshops benefit libraries?","answer":"Library attendance records from several cities show that more people visit when workshops are offered often.","options":["Library attendance records from several cities show that more people visit when workshops are offered often.","In these workshops, kids can learn skills like coding, building, and art.","Some people believe libraries should focus only on books and reading."],"video":"arg_facts-3"},{"kind":"blank","sentence":3,"ask":"Why did the author include the information about attendance records?","answer":"To provide evidence that workshops attract more visitors","options":["To explain how libraries organize books","To provide evidence that workshops attract more visitors","To show that workshops are difficult to plan","To compare libraries in different cities"],"video":"arg_facts-4"}]},{"kind":"passage","brief":"A third argument.","sentences":["Many communities should build more bike trails for residents.","Bike trails provide safe places for people to ride away from busy roads and traffic.","According to transportation studies, communities with dedicated bike paths often report fewer bicycle-related accidents than areas without them.","Bike trails also encourage people to spend more time exercising outdoors.","Some people believe communities should spend money on different projects instead.","However, many residents argue that safer routes and healthier lifestyles make bike trails a worthwhile investment."],"hint":"One sentence raises the objection. The next one answers it.","questions":[{"kind":"blank","sentence":3,"ask":"Which sentence uses a fact to support the argument that bike trails improve safety?","answer":"According to transportation studies, communities with dedicated bike paths often report fewer bicycle-related accidents than areas without them.","options":["According to transportation studies, communities with dedicated bike paths often report fewer bicycle-related accidents than areas without them.","Bike trails provide safe places for people to ride away from busy roads and traffic.","Bike trails also encourage people to spend more time exercising outdoors."],"video":"arg_facts-5"},{"kind":"blank","sentence":6,"ask":"Which sentence argues against the idea that communities should spend money on different projects instead?","answer":"However, many residents argue that safer routes and healthier lifestyles make bike trails a worthwhile investment.","options":["However, many residents argue that safer routes and healthier lifestyles make bike trails a worthwhile investment.","Some people believe communities should spend money on different projects instead.","Many communities should build more bike trails for residents."],"video":"arg_facts-6"},{"kind":"blank","sentence":3,"ask":"How does the fact about transportation studies support the author’s argument?","answer":"It provides evidence that bike trails can reduce accidents and make riding safer.","options":["It describes why some people disagree with building bike trails.","It shows that all residents use bike trails every day.","It explains how communities build bike trails.","It provides evidence that bike trails can reduce accidents and make riding safer."],"video":"arg_facts-7"}]},{"kind":"passage","brief":"One more.","sentences":["Communities should install more free water bottle refill stations in public parks.","These stations make it easier for visitors to stay hydrated while spending time outdoors.","Refill stations can also reduce the use of single-use plastic bottles, which helps decrease waste.","In addition, families can save money by refilling reusable bottles instead of purchasing drinks.","Some people think installing refill stations would cost too much money.","However, many residents believe the benefits to health and the environment make refill stations a worthwhile investment."],"hint":"Ask what reason this sentence gives for agreeing with the claim.","questions":[{"kind":"write","sentence":3,"ask":"How does this sentence support the author’s argument? “Refill stations can also reduce the use of single-use plastic bottles, which helps decrease waste.”","checks":[{"label":"Names the benefit","rule":{"type":"any","of":[{"type":"contains","any":["waste"]},{"type":"contains","any":["plastic"]},{"type":"contains","any":["environment"]},{"type":"contains","any":["pollut"]}]}},{"label":"Connects it to the claim","rule":{"type":"any","of":[{"type":"contains","any":["reason"]},{"type":"contains","any":["support"]},{"type":"contains","any":["why"]},{"type":"contains","any":["station"]},{"type":"contains","any":["install"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"It gives a reason to install the stations by showing they cut down on single-use plastic and reduce waste.","video":"arg_facts-8"}]}]}],"skillBuilders":{"arg_claim":{"id":"arg_sb_claim","title":"SB: Identify the Claim","standards":["5.9E (i)"],"skill":"Claim, reason, opposing view — one passage at a time","activities":[{"kind":"fix","mode":"select","bank":[],"brief":"In each passage, which sentence is the author’s claim?","hint":"A claim says what SHOULD happen. An opposing view starts with “Some people…”.","items":[{"given":"Schools should start the day a little later in the morning. Many students do not get enough sleep on school nights… Some people believe an early start helps families keep a steady routine.  →  ____","answer":"Schools should start the day a little later in the morning.","options":["Schools should start the day a little later in the morning.","Many students do not get enough sleep on school nights.","Some people believe an early start helps families keep a steady routine."],"video":"arg_sb_claim-1"},{"given":"Students should learn to type on a keyboard in elementary school. Typing helps kids finish their schoolwork faster… Some people think students should focus only on handwriting.  →  ____","answer":"Students should learn to type on a keyboard in elementary school.","options":["Students should learn to type on a keyboard in elementary school.","Typing helps kids finish their schoolwork faster and with fewer mistakes.","Some people think students should focus only on handwriting."],"video":"arg_sb_claim-2"}]},{"kind":"passage","brief":"Read the passage, then answer.","sentences":["Children should help with chores around the house.","Doing chores teaches kids how to be responsible and care for their home.","It also helps them learn skills they will use as adults.","Many families find that sharing chores makes the work easier for everyone.","Some people believe children are too busy with school to help at home.","Still, many parents agree that chores teach lessons that last a lifetime."],"hint":"The claim is the opinion. The rest are reasons for it.","questions":[{"kind":"blank","sentence":1,"ask":"What is the main claim the author makes in the passage?","answer":"Children should help with chores around the house.","options":["Doing chores teaches kids how to be responsible and care for their home.","Children should help with chores around the house.","Some people believe children are too busy with school to help at home."],"video":"arg_sb_claim-3"}]},{"kind":"passage","brief":"A second passage.","sentences":["Neighborhoods should build more public pickleball courts for families and residents.","Pickleball is a fast-growing sport that people of many ages can enjoy together.","Public courts provide a place for exercise, recreation, and community events.","Families can spend time outdoors while staying active and meeting new people.","The courts may also encourage residents to participate in healthy activities more often.","Some people think parks should use their space for other activities instead.","However, many residents believe pickleball courts give communities another way to stay active and connect with neighbors."],"hint":"One of these three is the claim and one is the opposing claim.","questions":[{"kind":"blank","sentence":1,"ask":"What is the main claim the author makes in the passage?","answer":"Neighborhoods should build more public pickleball courts for families and residents.","options":["Neighborhoods should build more public pickleball courts for families and residents.","Public courts provide a place for exercise, recreation, and community events.","Some people think parks should use their space for other activities instead."],"video":"arg_sb_claim-4"},{"kind":"blank","sentence":6,"ask":"Which sentence best states the opposing claim?","answer":"Some people think parks should use their space for other activities instead.","options":["Neighborhoods should build more public pickleball courts for families and residents.","Public courts provide a place for exercise, recreation, and community events.","Some people think parks should use their space for other activities instead."],"video":"arg_sb_claim-5"}]},{"kind":"passage","brief":"One more.","sentences":["Students should keep a daily journal at school.","Writing each day helps students improve their spelling and grammar.","A journal also gives students a private place to share their ideas and feelings.","Over time, students can look back and see how their writing has grown.","Some people believe journaling takes time away from other lessons.","However, many teachers find that daily writing makes students stronger and more confident."],"hint":"A reason answers \"why should we?\"","questions":[{"kind":"blank","sentence":2,"ask":"Which sentence is a reason the author gives to support the claim?","answer":"Writing each day helps students improve their spelling and grammar.","options":["Writing each day helps students improve their spelling and grammar.","Some people believe journaling takes time away from other lessons.","Students should keep a daily journal at school."],"video":"arg_sb_claim-6"}]}]},"arg_audience":{"id":"arg_sb_audience","title":"SB: The Audience","standards":["5.9E (iii)"],"skill":"Reading the clues that say who an argument is for","activities":[{"kind":"fix","mode":"drag","bank":["knights","wizards","dragon riders","potion makers","musicians","villagers"],"brief":"Each argument is written for one group. Which one?","hint":"Look at what the writer wants built. One group in the bank is never used.","items":[{"given":"Our winged beasts deserve new landing pads and roomy stables, because they need a safe place to rest their wings between long flights.  →  ____","answer":"dragon riders","video":"arg_sb_audience-1"},{"given":"A grand stage with bright enchanted lanterns is worth fighting for, because your songs and tales deserve a place to be heard by cheering crowds.  →  ____","answer":"musicians","video":"arg_sb_audience-2"},{"given":"Training matters, so insist on a practice yard with dummies and shields, because you must sharpen your sword and shield before the next great battle.  →  ____","answer":"knights","video":"arg_sb_audience-3"},{"given":"Mastering powerful magic requires a tower library of ancient scrolls, because spells cannot be learned without a quiet place to study them in peace.  →  ____","answer":"wizards","video":"arg_sb_audience-4"},{"given":"Healing the whole kingdom starts with a cauldron room of rare herbs, because brewing strong potions all year long demands the right space and ingredients.  →  ____","answer":"potion makers","video":"arg_sb_audience-5"}]},{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Students should be allowed to create a class pet rock museum.","Each student could decorate a rock, give it a funny name, and write a short description about its “personality.”","The museum would give students a creative way to practice writing and speaking.","It could also help classmates learn more about one another through humor and imagination.","Some people may think pet rocks are silly, but fun projects can still build useful classroom skills.","Teachers should consider adding a pet rock museum as a creative class activity."],"hint":"A different audience needs a different reason. Ask what each group cares about.","questions":[{"kind":"write","sentence":6,"ask":"Who is most likely the intended audience of this text?","checks":[{"label":"Names the audience","rule":{"type":"any","of":[{"type":"contains","any":["teacher"]},{"type":"contains","any":["educator"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":4}}],"model":"The audience is teachers, because the last sentence asks them to add the museum.","video":"arg_sb_audience-6"},{"kind":"blank","sentence":3,"ask":"What detail might they include to be more convincing for parents?","answer":"The project could help students practice writing and speaking skills.","options":["Some pet rocks might be painted with bright colors and patterns.","Students could give their pet rocks funny names and personalities.","The project could help students practice writing and speaking skills."],"video":"arg_sb_audience-7"},{"kind":"blank","sentence":2,"ask":"What detail might they include to be more convincing for students?","answer":"Students could vote for the funniest pet rock in the museum.","options":["Students could vote for the funniest pet rock in the museum.","Teachers could use the project to practice writing skills.","The museum could be displayed near the classroom door."],"video":"arg_sb_audience-8"}]},{"kind":"passage","brief":"One more.","sentences":["Students should join a lunchroom comedy club if one is offered at school.","Telling jokes and writing short skits can help students become more confident speakers.","Club members would learn how to organize ideas, use appropriate humor, and perform for an audience.","The club could also give students a fun way to make friends during the school year.","Although performing can feel nervous at first, practice can make it easier.","Students who enjoy making others laugh should consider joining the club."],"hint":"Who does the text keep saying \"you\" to?","questions":[{"kind":"write","sentence":6,"ask":"Who is the intended audience of the passage above?","checks":[{"label":"Names students","rule":{"type":"contains","any":["student"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":4}}],"model":"The audience is students, especially ones who enjoy making other people laugh.","video":"arg_sb_audience-9"}]}]},"arg_facts":{"id":"arg_sb_facts","title":"SB: Facts For an Argument","standards":["5.9E (ii)"],"skill":"Which facts help an argument, and which just sit there","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Schools should give students the chance to plant and care for their own gardens.","Working in a garden teaches young people responsibility, because seeds must be watered and weeded regularly in order to grow.","Studies have found that students who help grow vegetables are more willing to taste healthy foods they once avoided.","Gardening also lets children spend time outdoors instead of staring at screens all afternoon.","Gardens look most colorful when the flowers bloom in late spring.","By caring for living plants, students learn patience and discover how their own effort can produce something valuable."],"hint":"One sentence is true but does nothing for the argument.","questions":[{"kind":"blank","sentence":5,"ask":"Which sentence does NOT support the claim that gardening helps students?","answer":"Gardens look most colorful when the flowers bloom in late spring.","options":["Gardens look most colorful when the flowers bloom in late spring.","Working in a garden teaches young people responsibility.","Gardening also lets children spend time outdoors instead of staring at screens."],"video":"arg_sb_facts-1"},{"kind":"blank","sentence":5,"ask":"Which sentence would be a strong replacement?","answer":"Caring for a garden can teach students how plants change with the seasons.","options":["Some students prefer to eat lunch outside with their friends.","Caring for a garden can teach students how plants change with the seasons.","Many gardens are surrounded by tall wooden fences."],"video":"arg_sb_facts-2"},{"kind":"blank","sentence":3,"ask":"Which fact best supports the author’s claim that gardening helps students?","answer":"Growing vegetables can encourage students to eat healthier foods.","options":["Growing vegetables can encourage students to eat healthier foods.","Gardens often attract bees and colorful butterflies in the spring.","Many families grow flowers in their backyards at home."],"video":"arg_sb_facts-3"}]},{"kind":"passage","brief":"A second passage.","sentences":["Communities should plant more trees along their neighborhood streets.","Tall trees provide cooling shade that lowers temperatures on hot summer days, which helps people stay comfortable outdoors.","Their leaves also clean the air by absorbing harmful gases and releasing fresh oxygen for everyone to breathe.","Trees give birds and squirrels safe places to build nests and search for food.","Some people think planting trees costs too much money.","But cities save far more over time because shade trees lower cooling bills and reduce costly road repairs.","In addition, neighborhoods filled with trees often look more peaceful and welcoming to the families who live there."],"hint":"An author raises an objection on purpose, then knocks it down.","questions":[{"kind":"blank","sentence":5,"ask":"Which sentence is the opposing fact?","answer":"Some people think planting trees costs too much money.","options":["Some people think planting trees costs too much money.","Tall trees provide cooling shade that lowers temperatures on hot summer days.","Trees give birds and squirrels safe places to build nests."],"video":"arg_sb_facts-4"},{"kind":"blank","sentence":6,"ask":"Which sentence disproves it?","answer":"But cities save far more over time because shade trees lower cooling bills and reduce costly road repairs.","options":["But cities save far more over time because shade trees lower cooling bills and reduce costly road repairs.","Their leaves also clean the air by absorbing harmful gases.","Communities should plant more trees along their neighborhood streets."],"video":"arg_sb_facts-5"},{"kind":"blank","sentence":5,"ask":"Why did the author include a fact that argues against planting trees?","answer":"To show the opposing idea is wrong and make the argument stronger.","options":["To prove that trees really are too expensive to plant.","To show the opposing idea is wrong and make the argument stronger.","To change the subject to something new."],"video":"arg_sb_facts-6"}]},{"kind":"passage","brief":"One more.","sentences":["Schools should set aside time each day for students to read books they choose themselves.","Reading for enjoyment helps students build larger vocabularies and become stronger, more confident readers.","When children pick their own books, they are far more likely to stay interested and finish the story.","Quiet reading time also gives busy students a calm break during a long school day.","Recess usually lasts about twenty minutes.","Because reading widens the imagination and strengthens the mind, daily reading time is a valuable use of the school schedule."],"hint":"Ask what the sentence proves about the claim.","questions":[{"kind":"blank","sentence":2,"ask":"How did including this sentence support the author’s argument? “Reading for enjoyment helps students build larger vocabularies and become stronger, more confident readers.”","answer":"It supports the claim by giving a reason that free reading improves students’ skills.","options":["It explains that students should only read during recess.","It supports the claim by giving a reason that free reading improves students’ skills.","It describes how teachers choose books for the class library."],"video":"arg_sb_facts-7"}]}]}},"full":{"id":"arg_full","title":"Full Topic: Argumentative Texts","standards":["5.9E (i)","5.9E (ii)","5.9E (iii)"],"skill":"Claim, evidence and audience, in one piece of writing","activities":[{"kind":"passage","brief":"Read the passage, then answer the questions.","sentences":["Every student knows the worst part of lunch: staring at a warm, gooey brownie while choking down a pile of cold, rubbery green beans.","For this reason, our cafeteria should serve dessert before the main meal.","Eating dessert first would actually improve our health, because hungry students would still have plenty of room left for vegetables afterward.","Scientists have never officially proven that brownies cause harm, which practically means they are good for you.","Some adults claim that sugar makes children wild and impossible to control.","However, anyone who has watched a fifth grader after gym class knows that we were already wild to begin with.","A happy stomach leads to a happy brain, so the cafeteria should flip the menu and let dessert lead the way."],"hint":"One of these reasons proves nothing at all, even though it sounds scientific.","questions":[{"kind":"blank","sentence":2,"ask":"Which sentence best states the author’s claim?","answer":"For this reason, our cafeteria should serve dessert before the main meal.","options":["For this reason, our cafeteria should serve dessert before the main meal.","Some adults claim that sugar makes children wild and impossible to control.","Every student knows the worst part of lunch."],"video":"arg_full-1"},{"kind":"blank","sentence":4,"ask":"Which sentence gives the weakest support for the claim?","answer":"Scientists have never officially proven that brownies cause harm, which practically means they are good for you.","options":["Scientists have never officially proven that brownies cause harm, which practically means they are good for you.","Eating dessert first would actually improve our health, because hungry students would still have room for vegetables.","A happy stomach leads to a happy brain."],"video":"arg_full-2"}]},{"kind":"passage","brief":"A second argument.","sentences":["Parents, it is time to face an uncomfortable truth.","Children deserve to be paid for doing their chores.","Cleaning a messy bedroom is exhausting work, and no skilled worker should be expected to fold laundry for free.","Paying us for chores would also teach valuable money skills, since we would quickly learn to spend our earnings on candy and video games.","Hard workers always do their best when a reward is waiting, and nothing rewards a kid like cold, hard cash.","Of course, some parents argue that helping around the house is simply part of being in a family.","That may sound lovely on a greeting card, but a family is really a tiny business, and every business pays its workers.","A small weekly allowance would transform grumpy chore-doers into eager helpers almost overnight.","For the good of the entire household, parents should start handing out paychecks today."],"hint":"The very first word tells you who this is written for.","questions":[{"kind":"blank","sentence":2,"ask":"Which sentence is the author’s claim?","answer":"Children deserve to be paid for doing their chores.","options":["Children deserve to be paid for doing their chores.","Cleaning a messy bedroom is exhausting work.","Some parents argue that helping around the house is part of being in a family."],"video":"arg_full-3"},{"kind":"blank","sentence":6,"ask":"Which sentence gives a reason against the author’s claim?","answer":"Of course, some parents argue that helping around the house is simply part of being in a family.","options":["Of course, some parents argue that helping around the house is simply part of being in a family.","A small weekly allowance would transform grumpy chore-doers into eager helpers.","Hard workers always do their best when a reward is waiting."],"video":"arg_full-4"},{"kind":"write","sentence":1,"ask":"Who is the intended audience of this passage?","checks":[{"label":"Names parents","rule":{"type":"contains","any":["parent"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":4}}],"model":"The intended audience is parents, because the passage speaks to them directly from the first word.","video":"arg_full-5"}]},{"kind":"passage","brief":"A third argument.","sentences":["Students should be allowed to take a short nap during the school day.","Well-rested kids learn better and concentrate longer.","By lunchtime, many fifth graders are completely exhausted, yawning through math and daydreaming about their cozy pillows at home.","A quick afternoon nap could recharge their tired brains and help them remember much more of each lesson.","Some students enjoy collecting trading cards during recess.","Of course, some teachers worry that a daily nap would waste valuable learning minutes.","Still, supporters believe that a rested, focused student accomplishes far more in the end."],"hint":"One sentence in here is about something else entirely.","questions":[{"kind":"blank","sentence":5,"ask":"Which detail does NOT support the author’s claim?","answer":"Some students enjoy collecting trading cards during recess.","options":["Some students enjoy collecting trading cards during recess.","Well-rested kids learn better and concentrate longer.","A quick afternoon nap could recharge their tired brains."],"video":"arg_full-6"}]},{"kind":"passage","brief":"One more.","sentences":["Recess should be much longer, because fresh air and free time help students focus better once they return to class.","Running, climbing, and laughing give kids a chance to burn off extra energy that would otherwise turn into wiggling and whispering.","Longer recess could improve health, lift students’ moods, and even strengthen friendships across different grades.","Studies suggest that active bodies lead to sharper minds, so a longer break might actually raise test scores.","For all of these reasons, many students believe a longer recess would make the entire school day better."],"hint":"Claim, audience, and one piece of evidence.","questions":[{"kind":"write","sentence":1,"ask":"Finish the sentence: the author’s claim is…","checks":[{"label":"Names recess","rule":{"type":"contains","any":["recess"]}},{"label":"Says it should be longer","rule":{"type":"any","of":[{"type":"contains","any":["longer"]},{"type":"contains","any":["more time"]},{"type":"contains","any":["extend"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":5}}],"model":"that recess should be much longer, because it helps students focus when they return to class.","video":"arg_full-7"},{"kind":"write","sentence":5,"ask":"Finish the sentence: the intended audience is…","checks":[{"label":"Names the audience","rule":{"type":"any","of":[{"type":"contains","any":["student"]},{"type":"contains","any":["school"]},{"type":"contains","any":["teacher"]},{"type":"contains","any":["administrat"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":3}}],"model":"students, and the school leaders who decide how long recess lasts.","video":"arg_full-8"},{"kind":"write","sentence":4,"ask":"How does this sentence support the author’s claim? “Studies suggest that active bodies lead to sharper minds, so a longer break might actually raise test scores.”","checks":[{"label":"Names the evidence","rule":{"type":"any","of":[{"type":"contains","any":["stud"]},{"type":"contains","any":["research"]},{"type":"contains","any":["evidence"]},{"type":"contains","any":["fact"]}]}},{"label":"Says what it shows","rule":{"type":"any","of":[{"type":"contains","any":["test score"]},{"type":"contains","any":["sharper"]},{"type":"contains","any":["focus"]},{"type":"contains","any":["learn"]},{"type":"contains","any":["mind"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"It gives evidence from studies that being active sharpens the mind, which suggests a longer recess could raise test scores.","video":"arg_full-9"}]}]}},{"id":"topic_authors_purpose","title":"Author’s Purpose","short":"Author’s Purpose","state":"TX","grade":5,"domain":"Author's Purpose","standards":["5.10A","5.10B","5.10C"],"blurb":"Why the author wrote it, how it is organised, and what the features are for — then one full-topic proof.","icon":"🔍","core":[{"id":"apx_apm","title":"Author’s Purpose and Message","standards":["5.10A"],"skill":"Why the author wrote it, and what they want you to take away","activities":[{"kind":"passage","brief":"Read the article, then complete the statements.","sentences":["Aarav Patel, 10, enjoys knitting scarves and hats.","He learned the hobby from his grandmother and practiced every day after school.","Soon, Aarav was creating blankets and small stuffed animals for his family.","He shared pictures of his projects online, and many people liked his designs.","Aarav says knitting helps him stay calm and focused.","As Aarav improved, he joined a local craft club and taught younger kids how to knit simple projects.","He also helped collect handmade scarves for families during the winter.","Aarav says knitting taught him patience and confidence.","In the future, he hopes to become an engineer because he enjoys designing and building things."],"hint":"Purpose is WHY the author wrote it. Message is what they want you to believe afterwards.","questions":[{"kind":"write","sentence":6,"ask":"Finish the statement: The author included details about Aarav teaching younger kids to knit to…","checks":[{"label":"Says what it shows about Aarav","rule":{"type":"any","of":[{"type":"contains","any":["help"]},{"type":"contains","any":["teach"]},{"type":"contains","any":["share"]},{"type":"contains","any":["kind"]},{"type":"contains","any":["generous"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"show that Aarav enjoys helping others learn new skills.","video":"apx_apm-1"},{"kind":"write","sentence":8,"ask":"Finish the statement: The author most likely wrote the passage to…","checks":[{"label":"Names a hobby or knitting","rule":{"type":"any","of":[{"type":"contains","any":["hobb"]},{"type":"contains","any":["knit"]}]}},{"label":"Says what it does for young people","rule":{"type":"any","of":[{"type":"contains","any":["grow"]},{"type":"contains","any":["help"]},{"type":"contains","any":["learn"]},{"type":"contains","any":["confiden"]},{"type":"contains","any":["patien"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"show that hobbies can help young people grow and help others.","video":"apx_apm-2"}]},{"kind":"passage","brief":"Read the passage, then answer.","sentences":["Jalen tightened his helmet and watched the judges announce the winners of the skateboarding competition.","He had hoped to earn first place, but another skater received the top score.","For a moment, Jalen stared quietly at his board.","Then his best friend pointed out that Jalen had finally landed the difficult spin trick he had practiced for weeks.","As the crowd applauded, Jalen picked up his skateboard and headed back toward the practice ramps with a grin on his face."],"hint":"The message is about how Jalen handles losing. Which sentence shows him handling it?","questions":[{"kind":"blank","sentence":5,"ask":"Which sentence best supports the author’s message about staying positive after disappointment?","answer":"As the crowd applauded, Jalen picked up his skateboard and headed back toward the practice ramps with a grin on his face.","options":["As the crowd applauded, Jalen picked up his skateboard and headed back toward the practice ramps with a grin on his face.","He had hoped to earn first place, but another skater received the top score.","For a moment, Jalen stared quietly at his board."],"video":"apx_apm-3"},{"kind":"write","sentence":4,"ask":"Finish the statement: The author included details about Jalen practicing the spin trick for weeks to…","checks":[{"label":"Mentions the practice or hard work","rule":{"type":"any","of":[{"type":"contains","any":["practi"]},{"type":"contains","any":["hard work"]},{"type":"contains","any":["effort"]},{"type":"contains","any":["weeks"]}]}},{"label":"Says what it shows","rule":{"type":"any","of":[{"type":"contains","any":["pay"]},{"type":"contains","any":["paid"]},{"type":"contains","any":["worth"]},{"type":"contains","any":["proud"]},{"type":"contains","any":["success"]},{"type":"contains","any":["accomplish"]},{"type":"contains","any":["progress"]},{"type":"contains","any":["improv"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"show that his hard work paid off even though he did not win first place.","flag":"The video for question 4 leaves the answer blank — every other answer in this topic is written in. The model here is mine.","video":"apx_apm-4"}]},{"kind":"passage","brief":"A poem. Read it, then answer.","sentences":["The Great Cafeteria Disaster","I carried my lunch tray proud and tall, certain I would not trip at all.","The pizza slid, the pudding flew, and chocolate milk splashed on my shoe.","My best friend laughed so hard she cried, while french fries scattered far and wide.","The lunch lady handed me a mop and said, “At least the spill did stop!”","I bowed to cheers from every table, pretending I had planned the fable.","By the end of lunch, I had to admit the whole embarrassing moment was worth a bit."],"hint":"Look at how the speaker feels by the last line.","questions":[{"kind":"write","sentence":3,"ask":"Finish the statement: The author’s purpose for including the details about the flying pizza and spilled milk is to…","checks":[{"label":"Names the embarrassing moment","rule":{"type":"any","of":[{"type":"contains","any":["embarrass"]},{"type":"contains","any":["disaster"]},{"type":"contains","any":["mess"]},{"type":"contains","any":["accident"]},{"type":"contains","any":["mistake"]}]}},{"label":"Says it turns funny","rule":{"type":"any","of":[{"type":"contains","any":["funny"]},{"type":"contains","any":["laugh"]},{"type":"contains","any":["humor"]},{"type":"contains","any":["humour"]},{"type":"contains","any":["joke"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"show how embarrassing moments can become funny later.","video":"apx_apm-5"}]},{"kind":"passage","brief":"One more passage.","sentences":["Community gardens are becoming more common in cities across the country.","These gardens are often built in empty lots or near schools, and they provide fresh fruits and vegetables for local families.","In addition, gardens help the environment by cleaning the air and attracting bees and butterflies.","Some teachers use gardens to help students learn about science and healthy eating.","However, growing a garden takes hard work because plants need water, sunlight, and care each day.","Even with these challenges, many communities continue building gardens because they believe the benefits are important.","Community gardens show that people can improve their neighborhoods by working together."],"hint":"The last sentence usually says the message out loud.","questions":[{"kind":"blank","sentence":4,"ask":"What is the most likely reason the author included the information about teachers and students?","answer":"to describe one benefit of community gardens","options":["to explain why science classes are difficult","to describe one benefit of community gardens","to show how students become gardeners","to explain why schools need larger playgrounds"],"video":"apx_apm-6"},{"kind":"write","sentence":7,"ask":"Finish the statement: The author’s message in the passage is…","checks":[{"label":"Mentions working together or community","rule":{"type":"any","of":[{"type":"contains","any":["together"]},{"type":"contains","any":["communit"]},{"type":"contains","any":["neighbo"]}]}},{"label":"Says people can improve things","rule":{"type":"any","of":[{"type":"contains","any":["improve"]},{"type":"contains","any":["better"]},{"type":"contains","any":["help"]},{"type":"contains","any":["change"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"people can improve their communities by working together to create gardens.","video":"apx_apm-7"}]}]},{"id":"apx_ts","title":"Text Structure","standards":["5.10B"],"skill":"How a text is organised, and why the author chose that shape","activities":[{"kind":"passage","brief":"Read the three paragraphs. Each question names the paragraph it is about.","sentences":["(1) When the city announced plans to replace the old skate park with a parking lot, many students were disappointed. The ramps were cracked and damaged, so city leaders believed repairs would cost too much money. However, several students decided to work together to save the park.","(2) First, the students created posters explaining why the skate park mattered to the community. Next, they organized a weekend event where skaters performed tricks while volunteers collected donations for repairs. Soon, local businesses offered supplies and paint to help improve the park.","(3) The city eventually decided to repair the skate park instead of tearing it down. Workers fixed the broken ramps, added brighter lights, and painted colorful designs across the walls. When the repairs were finished, families and students gathered for a community celebration at the grand reopening. By the end of the summer, the skate park had once again become one of the busiest places in the neighborhood."],"hint":"Problem and solution, then the steps in order, then what happened because of them.","questions":[{"kind":"write","sentence":1,"ask":"What is the author’s purpose for presenting paragraph 1 as a problem-and-solution structure?","checks":[{"label":"Mentions the problem or how students responded","rule":{"type":"any","of":[{"type":"contains","any":["problem"]},{"type":"contains","any":["respond"]},{"type":"contains","any":["react"]},{"type":"contains","any":["solve"]},{"type":"contains","any":["save"]}]}},{"label":"Mentions readers understanding","rule":{"type":"any","of":[{"type":"contains","any":["understand"]},{"type":"contains","any":["readers"]},{"type":"contains","any":["show"]},{"type":"contains","any":["explain"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"To help readers understand how students responded to a community problem.","video":"apx_ts-1"},{"kind":"write","sentence":2,"ask":"Finish the sentence: The author organized paragraph 2 in chronological order to…","checks":[{"label":"Mentions steps or sequence","rule":{"type":"any","of":[{"type":"contains","any":["step"]},{"type":"contains","any":["order"]},{"type":"contains","any":["sequence"]},{"type":"contains","any":["first"]}]}},{"label":"Mentions saving the park","rule":{"type":"any","of":[{"type":"contains","any":["save"]},{"type":"contains","any":["skate park"]},{"type":"contains","any":["park"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"explain the steps students took to help save the skate park.","video":"apx_ts-2"},{"kind":"write","sentence":3,"ask":"Finish the sentence: The author uses a cause-and-effect structure for paragraph 3 most likely to…","checks":[{"label":"Mentions results or effects","rule":{"type":"any","of":[{"type":"contains","any":["result"]},{"type":"contains","any":["effect"]},{"type":"contains","any":["outcome"]},{"type":"contains","any":["happened"]},{"type":"contains","any":["led to"]}]}},{"label":"Mentions the teamwork or students","rule":{"type":"any","of":[{"type":"contains","any":["teamwork"]},{"type":"contains","any":["student"]},{"type":"contains","any":["work"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"show the positive results of the students’ teamwork.","video":"apx_ts-3"},{"kind":"blank","sentence":3,"ask":"Which sentence from paragraph 3 best shows the EFFECT of the students’ teamwork?","answer":"By the end of the summer, the skate park had once again become one of the busiest places in the neighborhood.","options":["By the end of the summer, the skate park had once again become one of the busiest places in the neighborhood.","The city eventually decided to repair the skate park instead of tearing it down.","Workers fixed the broken ramps, added brighter lights, and painted colorful designs across the walls."],"video":"apx_ts-4"}]},{"kind":"passage","brief":"Two more passages.","sentences":["Escape rooms are popular attractions where players solve puzzles and search for clues before time runs out. Many rooms have exciting themes such as haunted mansions, secret laboratories, or space stations. Players examine hidden objects, decode messages, and unlock doors while working together as a team. The mysterious setting and fast pace make escape rooms exciting for many people.","Because escape rooms require teamwork, many teachers and youth programs now use them as learning activities. Students practicing communication and problem-solving skills often become more confident while completing challenges together. As a result, some schools create classroom escape rooms to review science, math, or history lessons in a more interactive way.","The Rise of Food Trucks. Food trucks have become more popular in many cities across the country. Years ago, most food trucks sold simple meals like hot dogs and sandwiches at parks or construction sites. Over time, chefs began offering many different foods, including tacos, barbecue, and desserts. Because food trucks can travel to busy events and neighborhoods, many owners found new ways to reach customers. Some cities even hold food truck festivals where families can try meals from several trucks in one place. Today, food trucks are an important part of food culture in many communities because they provide creative meals at affordable prices."],"hint":"“Years ago… Over time… Today” is a clue to the structure.","questions":[{"kind":"blank","sentence":1,"ask":"What is the most likely reason the author uses a descriptive text structure in the first paragraph?","answer":"To help readers imagine what escape rooms are like","options":["To help readers imagine what escape rooms are like","To explain the steps needed to build an escape room","To compare escape rooms with video games","To show how escape rooms became popular over time"],"video":"apx_ts-5"},{"kind":"write","sentence":2,"ask":"Finish the sentence: The author uses a cause-and-effect structure for the second paragraph most likely to…","checks":[{"label":"Mentions teamwork or skills","rule":{"type":"any","of":[{"type":"contains","any":["teamwork"]},{"type":"contains","any":["skill"]},{"type":"contains","any":["problem-solving"]},{"type":"contains","any":["communicat"]}]}},{"label":"Mentions students or learning","rule":{"type":"any","of":[{"type":"contains","any":["student"]},{"type":"contains","any":["learn"]},{"type":"contains","any":["school"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"explain how escape rooms help students build teamwork and problem-solving skills.","video":"apx_ts-6"},{"kind":"blank","sentence":3,"ask":"A student says the author used a problem-and-solution structure to explain food trucks. Is the student correct?","answer":"FALSE","options":["TRUE","FALSE"],"video":"apx_ts-7"},{"kind":"blank","sentence":3,"ask":"The author presents the food truck information in which text structure?","answer":"chronological","options":["chronological","problem and solution","compare and contrast","descriptive"],"video":"apx_ts-8"},{"kind":"write","sentence":3,"ask":"…to do what? Finish the sentence: the author uses that structure to…","checks":[{"label":"Mentions change over time","rule":{"type":"any","of":[{"type":"contains","any":["over time"]},{"type":"contains","any":["changed"]},{"type":"contains","any":["became"]},{"type":"contains","any":["grew"]},{"type":"contains","any":["history"]}]}},{"label":"Mentions food trucks","rule":{"type":"contains","any":["food truck"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"explain how food trucks changed and became more popular over time.","video":"apx_ts-8"}]}]},{"id":"apx_pgf","title":"Print and Graphic Features","standards":["5.10C"],"skill":"Headings, captions, photos and charts — and what each one is for","flag":"The paper shows a real photograph, chart or timeline here. The deck text cannot carry an image, so each feature is described in words inside the passage. Check that the questions still make sense against the description.","activities":[{"kind":"passage","brief":"Read the passage. The features on the paper are described in brackets.","sentences":["Libraries Help Communities","Public libraries are places where people can read, learn, and explore new ideas for free. Today, libraries offer books, computers, digital books, and educational programs for children and adults. Many libraries also provide free internet access and quiet spaces for studying.","[Subheading] The First Free Libraries","Long ago, books were expensive, and many families could not afford to own them. In 1833, Peterborough, New Hampshire, opened one of the first free public libraries in the United States. Citizens could borrow books without paying fees. Soon, other towns began creating libraries because they believed education was important for everyone.","[Photograph] A small old wooden house with a peaked roof. Caption: One of the first free public libraries in Peterborough, NH.","During the late 1800s, libraries became more common across the country. Andrew Carnegie donated money to help build more than 1,600 libraries. These libraries gave communities access to books and learning opportunities.","Today, libraries continue to change. Visitors can borrow electronic books, use computers, and attend free programs.","[Did You Know? box] Many libraries host free summer reading programs for children."],"hint":"Each feature does a job. Ask what the reader gets from it that the plain text does not give.","questions":[{"kind":"write","sentence":5,"ask":"Why did the author include the photograph?","checks":[{"label":"Mentions seeing or picturing","rule":{"type":"any","of":[{"type":"contains","any":["see"]},{"type":"contains","any":["look"]},{"type":"contains","any":["picture"]},{"type":"contains","any":["visual"]},{"type":"contains","any":["imagine"]},{"type":"contains","any":["show"]}]}},{"label":"Mentions the library","rule":{"type":"contains","any":["librar"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"To help readers better understand what one of the first public libraries looked like.","video":"apx_pgf-1"},{"kind":"write","sentence":8,"ask":"Why did the author include the “Did You Know?” box at the bottom?","checks":[{"label":"Mentions an extra fact","rule":{"type":"any","of":[{"type":"contains","any":["fact"]},{"type":"contains","any":["extra"]},{"type":"contains","any":["additional"]},{"type":"contains","any":["more information"]},{"type":"contains","any":["interesting"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":5}}],"model":"To give readers an additional fact about libraries.","video":"apx_pgf-2"},{"kind":"write","sentence":3,"ask":"What was the author’s purpose for using subheadings?","checks":[{"label":"Mentions organising or topics","rule":{"type":"any","of":[{"type":"contains","any":["organi"]},{"type":"contains","any":["topic"]},{"type":"contains","any":["section"]},{"type":"contains","any":["main idea"]},{"type":"contains","any":["find"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":5}}],"model":"To organize information and help readers identify main topics.","video":"apx_pgf-3"},{"kind":"blank","sentence":5,"ask":"True or false: the caption explains that the first free public library in Peterborough, New Hampshire burned down.","answer":"FALSE","options":["TRUE","FALSE"],"video":"apx_pgf-4"}]},{"kind":"passage","brief":"A second passage, with its features described.","sentences":["Should Schools Keep Printed Textbooks?","[Subheading] Benefits of Printed Textbooks","Many schools use laptops and tablets, but printed textbooks are still important. Paper books help students focus and avoid distractions from games or websites. Many students also remember information better when reading from a physical page.","[Photograph] A student at a desk with a highlighter and an open book. Caption: A student highlights important information.","[Subheading] Technology and Learning","Digital books give students quick access to information and activities. However, too much screen time can cause distractions and eyestrain. Using both textbooks and technology can support learning.","[Chart] Student Learning Preferences — a bar chart with two bars, Printed Textbooks and Digital Books, showing how many students prefer each.","[Subheading] Finding the Right Balance","Schools do not have to choose only one learning tool. Many teachers use both printed textbooks and digital books to support student learning and give students different ways to practice skills."],"hint":"A photograph shows; a caption tells you what you are seeing; a chart compares.","questions":[{"kind":"write","sentence":4,"ask":"What information does the photograph provide the reader with?","checks":[{"label":"Mentions the textbook or reading","rule":{"type":"any","of":[{"type":"contains","any":["textbook"]},{"type":"contains","any":["book"]},{"type":"contains","any":["read"]},{"type":"contains","any":["highlight"]}]}},{"label":"Mentions learning or use","rule":{"type":"any","of":[{"type":"contains","any":["learn"]},{"type":"contains","any":["use"]},{"type":"contains","any":["study"]},{"type":"contains","any":["how"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"It helps readers understand how printed textbooks are used for learning.","video":"apx_pgf-5"},{"kind":"write","sentence":4,"ask":"How does the caption help the reader?","checks":[{"label":"Mentions what the student is doing","rule":{"type":"any","of":[{"type":"contains","any":["highlight"]},{"type":"contains","any":["important"]},{"type":"contains","any":["doing"]},{"type":"contains","any":["using"]}]}},{"label":"Mentions explaining or telling","rule":{"type":"any","of":[{"type":"contains","any":["explain"]},{"type":"contains","any":["tell"]},{"type":"contains","any":["describe"]},{"type":"contains","any":["understand"]},{"type":"contains","any":["know"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"It explains that the student is using a printed textbook to highlight important information.","video":"apx_pgf-6"},{"kind":"blank","sentence":7,"ask":"What is the most likely reason the author includes the chart?","answer":"to show why students prefer different learning tools","options":["to explain how digital books are made","to entertain readers with a chart","to show events in time order","to show why students prefer different learning tools"],"video":"apx_pgf-7"}]}]}],"skillBuilders":{"apx_apm":{"id":"apx_sb_apm","title":"SB: Author’s Purpose and Message","standards":["5.10A"],"skill":"Purpose and message, one story at a time","activities":[{"kind":"passage","brief":"Read the passage, then answer.","sentences":["Ethan wanted to save money, so he decided to cut his own hair before school picture day. After watching two short videos online, he felt completely confident. At first, everything seemed fine, but then the clippers made a loud buzzing sound and removed a large patch of hair above his ear. Ethan tried to fix the mistake by trimming the other side, but that only made his hair shorter and more uneven.","When he walked into school the next morning, his friends stared for a second before bursting into laughter. Even his teacher had trouble hiding a smile during attendance. By lunchtime, several students were calling Ethan “The Lawn Mower” because of the strange lines shaved into his hair. Instead of getting upset, Ethan joked about the disaster and claimed he was “starting a new fashion trend.”"],"hint":"Inform, entertain, teach or persuade — which one is this?","questions":[{"kind":"blank","sentence":2,"ask":"Why did the author include details about students calling Ethan “The Lawn Mower”?","answer":"To show how students reacted to Ethan’s haircut","options":["To explain why Ethan became upset with his classmates","To show how students reacted to Ethan’s haircut","To describe how students create funny nicknames"],"video":"apx_sb_apm-1"},{"kind":"blank","sentence":1,"ask":"What is the most likely purpose the author wrote this passage?","answer":"To entertain readers with a school story","options":["To inform readers about recycling","To entertain readers with a school story","To teach readers about a science experiment","To persuade readers that the school needs more bike racks"],"video":"apx_sb_apm-2"}]},{"kind":"passage","brief":"A second passage.","sentences":["Benji could not wait for the school’s “Inventor Day” competition. He spent three weeks building a machine that was supposed to feed his dog automatically. On the morning of the contest, Benji proudly placed the invention on the table and pressed the power button. Instead of dropping dog food into the bowl, the machine launched pieces of kibble across the cafeteria like popcorn. One piece even landed in the principal’s coffee cup.","Students burst into laughter while Benji scrambled to unplug the machine. At first, he wanted to hide under the table, but then he started laughing too. By the end of the contest, several students asked Benji to demonstrate the “flying dog food machine” again because they thought it was the funniest invention at the event."],"hint":"The message is in how Benji chooses to react.","questions":[{"kind":"blank","sentence":2,"ask":"What is the author’s message?","answer":"Mistakes can become enjoyable when people choose a positive attitude","options":["Competitions should have stricter rules for inventions","Mistakes can become enjoyable when people choose a positive attitude","Inventing machines requires advanced scientific knowledge"],"video":"apx_sb_apm-3"},{"kind":"blank","sentence":2,"ask":"Which sentence best supports that message?","answer":"At first, he wanted to hide under the table, but then he started laughing too.","options":["At first, he wanted to hide under the table, but then he started laughing too.","He spent three weeks building a machine that was supposed to feed his dog automatically.","One piece even landed in the principal’s coffee cup."],"video":"apx_sb_apm-4"},{"kind":"write","sentence":2,"ask":"Explain your reasoning.","checks":[{"label":"Mentions laughing or attitude","rule":{"type":"any","of":[{"type":"contains","any":["laugh"]},{"type":"contains","any":["attitude"]},{"type":"contains","any":["positive"]},{"type":"contains","any":["chose"]},{"type":"contains","any":["decided"]}]}},{"label":"Connects to the message","rule":{"type":"any","of":[{"type":"contains","any":["mistake"]},{"type":"contains","any":["enjoy"]},{"type":"contains","any":["instead"]},{"type":"contains","any":["rather than"]},{"type":"contains","any":["hide"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"It shows Benji choosing to laugh instead of hiding, which is exactly what the message says — a mistake became enjoyable because of his attitude.","video":"apx_sb_apm-4"}]},{"kind":"passage","brief":"One more, with numbered sentences.","sentences":["Ronnie wanted to win the school marble tournament more than anything.","During the first round, another player dropped a shiny blue marble under the table.","Ronnie picked it up and thought about keeping it because it was smoother than his own marbles.","Then he imagined how upset he would feel if someone kept one of his favorites.","Ronnie handed the marble back, and the other player smiled and thanked him."],"hint":"Honesty is an action. Which sentence is the action?","questions":[{"kind":"blank","sentence":5,"ask":"Which sentence best supports the author’s message about honesty?","answer":"Ronnie handed the marble back, and the other player smiled and thanked him.","options":["Then he imagined how upset he would feel if someone kept one of his favorites.","Ronnie wanted to win the school marble tournament more than anything.","Ronnie handed the marble back, and the other player smiled and thanked him."],"video":"apx_sb_apm-5"}]}]},"apx_ts":{"id":"apx_sb_ts","title":"SB: Text Structures","standards":["5.10B"],"skill":"Chronological, cause and effect, compare and contrast — and why each was chosen","activities":[{"kind":"passage","brief":"Read the passage, then answer.","sentences":["(1) Many students struggle to keep their backpacks organized during the school week. Because papers become crumpled and homework often disappears, some students arrive to class feeling unprepared and stressed. Teachers also lose valuable class time while students search for missing assignments and supplies. As a result, one middle school created “Backpack Check Fridays” to help students stay organized.","(2) First, students sort papers into folders for each subject. Next, they sharpen pencils and check planners for missing assignments. Finally, teachers inspect backpacks to make sure students are prepared for the following week. As a result, many students forget fewer assignments and arrive more prepared for class."],"hint":"Chronological order shows events in order or the steps in a process.","questions":[{"kind":"write","sentence":1,"ask":"Finish the sentence: The author uses a problem-and-solution structure in the first paragraph to explain…","checks":[{"label":"Names the problem","rule":{"type":"any","of":[{"type":"contains","any":["disorgani"]},{"type":"contains","any":["backpack"]},{"type":"contains","any":["problem"]},{"type":"contains","any":["messy"]}]}},{"label":"Names the solution","rule":{"type":"any","of":[{"type":"contains","any":["solution"]},{"type":"contains","any":["solve"]},{"type":"contains","any":["backpack check"]},{"type":"contains","any":["created"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"how problems caused by disorganized backpacks led the school to create a solution.","video":"apx_sb_ts-1"},{"kind":"write","sentence":2,"ask":"Why does the author organize the second paragraph in chronological order?","checks":[{"label":"Mentions steps or sequence","rule":{"type":"any","of":[{"type":"contains","any":["step"]},{"type":"contains","any":["sequence"]},{"type":"contains","any":["order"]},{"type":"contains","any":["first"]}]}},{"label":"Mentions Backpack Check Fridays or students","rule":{"type":"any","of":[{"type":"contains","any":["backpack"]},{"type":"contains","any":["student"]},{"type":"contains","any":["friday"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"To help readers understand the sequence of steps students follow during Backpack Check Fridays.","video":"apx_sb_ts-2"}]},{"kind":"passage","brief":"A poem, then a passage.","sentences":["First, Marco carried pizzas down the hall with pride, balancing three giant boxes stacked high at his side. Next, he pushed the gym door open with his shoe, but the slippery floor sent the pizzas flying too.","Because the pizzas landed upside down on the floor, students burst into laughter louder than before. As a result, Marco bowed like a chef on TV, and the principal tossed him napkins with a grin.","Both skateboarding and roller skating are popular activities for students who enjoy fast-paced sports. Skateboarding requires riders to balance on a narrow board, while roller skating uses boots with wheels attached. Unlike roller skates, skateboards can perform tricks more easily at skate parks. However, roller skates often provide more stability for beginners learning balance and coordination."],"hint":"“Because… As a result…” is cause and effect. “Both… while… Unlike…” is compare and contrast.","questions":[{"kind":"blank","sentence":1,"ask":"Why does the poet organize the first stanza in chronological order?","answer":"to explain the sequence of events that led to the pizza accident","options":["to explain the sequence of events that led to the pizza accident","to describe what the pizzas looked like before they fell","to compare Marco’s actions with the principal’s actions"],"video":"apx_sb_ts-3"},{"kind":"write","sentence":2,"ask":"Why does the author organize the second stanza using a cause-and-effect structure?","checks":[{"label":"Mentions the accident or fall","rule":{"type":"any","of":[{"type":"contains","any":["accident"]},{"type":"contains","any":["fell"]},{"type":"contains","any":["fall"]},{"type":"contains","any":["dropped"]},{"type":"contains","any":["pizzas"]}]}},{"label":"Mentions the reactions","rule":{"type":"any","of":[{"type":"contains","any":["react"]},{"type":"contains","any":["laugh"]},{"type":"contains","any":["caused"]},{"type":"contains","any":["result"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"To explain how Marco’s accident caused the students’ reactions.","video":"apx_sb_ts-4"},{"kind":"blank","sentence":3,"ask":"Three students explain the skating passage. Art: “compare-and-contrast, to explain how skateboarding and roller skating are alike and different.” Manny: “problem and solution, to explain how they are good for the skater.” Will: “chronological, to explain the order of learning new skating skills.” Who is correct?","answer":"Art","options":["Art","Manny","Will"],"video":"apx_sb_ts-5"}]}]},"apx_pgf":{"id":"apx_sb_pgf","title":"SB: Print and Graphic Features","standards":["5.10C"],"skill":"Headings, italics, bold, photographs and timelines — one feature at a time","flag":"The paper shows a real photograph, chart or timeline here. The deck text cannot carry an image, so each feature is described in words inside the passage. Check that the questions still make sense against the description.","activities":[{"kind":"passage","brief":"Read the passage. The features are described in brackets.","sentences":["The Secret Snack Thief","[Heading] Missing Snacks","Every Friday, snacks disappeared from Ms. Lee’s classroom cabinet before recess. Students blamed one another, but nobody could explain why the crackers and granola bars kept vanishing. [In italics:] Someone must be sneaking into the room early, thought Javier as he examined the cabinet carefully.","[Heading] Looking for Clues","Javier noticed a trail of tiny crumbs leading toward the reading corner. Near a beanbag chair, he spotted an open backpack stuffed with snack wrappers. Suddenly, Peanut the class hamster darted across the floor carrying a cracker almost as large as his head. Javier laughed when he realized the “snack thief” had whiskers and tiny paws instead of fingerprints.","[Photograph] A hamster running across a classroom floor with a cracker. Caption: Peanut the hamster races across the classroom with a stolen cracker."],"hint":"Italics often mark what a character is thinking.","questions":[{"kind":"write","sentence":4,"ask":"Why did the author include the heading “Looking for Clues”?","checks":[{"label":"Mentions what the section is about","rule":{"type":"any","of":[{"type":"contains","any":["about"]},{"type":"contains","any":["section"]},{"type":"contains","any":["topic"]},{"type":"contains","any":["main idea"]},{"type":"contains","any":["happen"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"To help readers identify what the section is mainly about.","video":"apx_sb_pgf-1"},{"kind":"blank","sentence":3,"ask":"What is the author’s purpose for using italic print in the first paragraph?","answer":"To show Javier’s thoughts during the investigation","options":["To help readers identify the title of another text","To show Javier’s thoughts during the investigation","To describe the sound Peanut made while running away"],"video":"apx_sb_pgf-2"}]},{"kind":"passage","brief":"Two more passages, features described.","sentences":["Many students at Lincoln Middle School believe recess should be longer each day. They argue that extra recess would help students exercise, relax, and focus better in class. Some teachers agree because active students are often more [in bold:] productive during lessons. However, other people think a longer recess would take away important learning time. Even so, many students feel the benefits of extra movement and social time make a longer recess a good idea.","[Photograph] Students playing basketball and relaxing on a sunny playground.","The Rise of Gaming Tournaments. Video game tournaments have become more popular with kids and teenagers in recent years. Many students now watch gamers compete online in games such as Minecraft and Rocket League. Some schools have even started esports clubs where students practice teamwork and strategy together.","[Timeline] 2018: Most school gaming clubs meet just for fun. 2020: More students begin watching tournaments online. 2022: Schools start creating official esports teams. 2025: Student gaming tournaments become more common nationwide."],"hint":"Bold makes one word louder. A timeline shows change in order.","questions":[{"kind":"write","sentence":2,"ask":"Finish the sentence: The author includes the photograph in the passage to help readers…","checks":[{"label":"Mentions seeing students at recess","rule":{"type":"any","of":[{"type":"contains","any":["see"]},{"type":"contains","any":["picture"]},{"type":"contains","any":["visual"]},{"type":"contains","any":["imagine"]},{"type":"contains","any":["show"]}]}},{"label":"Mentions recess or fun","rule":{"type":"any","of":[{"type":"contains","any":["recess"]},{"type":"contains","any":["relax"]},{"type":"contains","any":["fun"]},{"type":"contains","any":["play"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"see students relaxing and having fun during recess.","video":"apx_sb_pgf-3"},{"kind":"blank","sentence":1,"ask":"What is the reason the author included the bolded word “productive”?","answer":"to emphasize that teachers believe students work better after recess","options":["to emphasize that teachers believe students work better after recess","to explain how recess helps students stay healthy","to compare students who like recess with students who do not"],"video":"apx_sb_pgf-4"},{"kind":"write","sentence":4,"ask":"What is the most likely reason the author included the timeline?","checks":[{"label":"Mentions change over time","rule":{"type":"any","of":[{"type":"contains","any":["over time"]},{"type":"contains","any":["popular"]},{"type":"contains","any":["grew"]},{"type":"contains","any":["changed"]},{"type":"contains","any":["order"]},{"type":"contains","any":["years"]}]}},{"label":"Mentions gaming or tournaments","rule":{"type":"any","of":[{"type":"contains","any":["gaming"]},{"type":"contains","any":["tournament"]},{"type":"contains","any":["esports"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"To help readers understand how gaming tournaments became more popular over time.","video":"apx_sb_pgf-5"}]}]}},"full":{"id":"apx_full","title":"Full Topic: Author’s Purpose","standards":["5.10A","5.10B","5.10C"],"skill":"Purpose, structure and features, in one piece of writing","flag":"The paper shows a real photograph, chart or timeline here. The deck text cannot carry an image, so each feature is described in words inside the passage. Check that the questions still make sense against the description.","activities":[{"kind":"passage","brief":"Read the passage. Its features are described in brackets.","sentences":["[Heading] Morning Confusion","In 2012, visitors at the Tokyo Sea Life Park were shocked when a penguin escaped from its enclosure and disappeared into Tokyo Bay. Workers searched for the penguin for weeks, but the clever bird avoided capture by swimming through the busy harbor.","[Timeline] March 3: The penguin escapes from the zoo. March 10: People spot the penguin swimming near fishing boats. April 2: News reporters film the penguin diving into the bay. May 24: Zoo workers safely capture the penguin.","News stations shared updates every day, and people across Japan became curious about where the penguin might appear next.","[Heading] A Famous Fugitive","Photographs of the penguin appeared online and on television almost every day. Many people joked that the penguin was enjoying a “vacation” around the city. Although the escape caused problems for zoo workers, the penguin quickly became one of the most famous animals in Japan.","[Photograph] A penguin swimming in open water with boats behind it. Caption: The escaped penguin swimming through Tokyo Bay."],"hint":"Three features, three jobs.","questions":[{"kind":"write","sentence":3,"ask":"What does the timeline help readers understand?","checks":[{"label":"Mentions order or events","rule":{"type":"any","of":[{"type":"contains","any":["order"]},{"type":"contains","any":["event"]},{"type":"contains","any":["sequence"]},{"type":"contains","any":["when"]},{"type":"contains","any":["dates"]}]}},{"label":"Mentions the escape or penguin","rule":{"type":"any","of":[{"type":"contains","any":["escape"]},{"type":"contains","any":["penguin"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"The order of important events during the penguin’s escape.","video":"apx_full-1"},{"kind":"write","sentence":7,"ask":"What is the most likely reason the author includes the photograph?","checks":[{"label":"Mentions seeing or visualising","rule":{"type":"any","of":[{"type":"contains","any":["see"]},{"type":"contains","any":["visual"]},{"type":"contains","any":["picture"]},{"type":"contains","any":["imagine"]},{"type":"contains","any":["show"]}]}},{"label":"Mentions the penguin swimming","rule":{"type":"any","of":[{"type":"contains","any":["penguin"]},{"type":"contains","any":["swim"]},{"type":"contains","any":["bay"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"To help readers visualize the escaped penguin swimming in Tokyo Bay.","video":"apx_full-2"},{"kind":"write","sentence":5,"ask":"Why did the author include headings?","checks":[{"label":"Mentions sections or topics","rule":{"type":"any","of":[{"type":"contains","any":["section"]},{"type":"contains","any":["topic"]},{"type":"contains","any":["about"]},{"type":"contains","any":["organi"]},{"type":"contains","any":["main idea"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"To help readers identify what each section of the passage is mainly about.","video":"apx_full-3"}]},{"kind":"passage","brief":"A second passage.","sentences":["In 2021, many restaurants across the United States struggled to keep enough ketchup packets in stock. Because more families were ordering takeout meals during that time, restaurants used far more packets than usual. As a result, some restaurants limited how many packets customers could take with each order. News stories and social media posts about the shortage quickly spread online, and many students joked that ketchup packets had become “more valuable than gold.”","To solve the ketchup shortage, restaurant companies increased shipments and encouraged customers to use ketchup bottles at home instead of extra packets. Although the shortage was short, it showed how quickly small problems can affect many people."],"hint":"“Because… As a result” in the first paragraph. “To solve…” in the second.","questions":[{"kind":"write","sentence":1,"ask":"Why does the author organize the first paragraph using a cause-and-effect structure?","checks":[{"label":"Names the cause","rule":{"type":"any","of":[{"type":"contains","any":["takeout"]},{"type":"contains","any":["ordering"]},{"type":"contains","any":["families"]},{"type":"contains","any":["demand"]}]}},{"label":"Names the effect","rule":{"type":"any","of":[{"type":"contains","any":["shortage"]},{"type":"contains","any":["ran out"]},{"type":"contains","any":["caused"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"To explain how increased takeout orders caused the ketchup shortage.","video":"apx_full-4"},{"kind":"blank","sentence":2,"ask":"Which sentence best supports the author’s message that small problems can affect many people?","answer":"Although the shortage was short, it showed how quickly small problems can affect many people.","options":["Although the shortage was short, it showed how quickly small problems can affect many people.","To solve the ketchup shortage, restaurant companies increased shipments.","Many students joked that ketchup packets had become “more valuable than gold.”"],"video":"apx_full-5"},{"kind":"write","sentence":2,"ask":"What is the author’s purpose for organizing the second paragraph as a problem-and-solution structure?","checks":[{"label":"Mentions solving","rule":{"type":"any","of":[{"type":"contains","any":["solve"]},{"type":"contains","any":["solution"]},{"type":"contains","any":["fix"]},{"type":"contains","any":["ended"]}]}},{"label":"Mentions the shortage or restaurants","rule":{"type":"any","of":[{"type":"contains","any":["shortage"]},{"type":"contains","any":["restaurant"]},{"type":"contains","any":["ketchup"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"To explain how restaurants solved the ketchup shortage.","video":"apx_full-6"}]},{"kind":"passage","brief":"One more.","sentences":["In 2013, thousands of people gathered in Seattle, Washington, to break the world record for the largest snowball fight. First, volunteers reviewed safety rules and handed out gloves. Next, teams moved into different sections of the park while trucks delivered snow for the competition. Finally, a loud horn signaled the start of the event, and snowballs flew across the park.","Many participants said the event brought people together through teamwork and laughter. Some even returned the next year with matching costumes and team names. The event showed that simple activities can create memorable experiences."],"hint":"First, Next, Finally.","questions":[{"kind":"blank","sentence":1,"ask":"Bethany thinks the author used chronological order to explain the steps of the snowball fight event. Is she correct?","answer":"TRUE","options":["TRUE","FALSE"],"video":"apx_full-7"},{"kind":"write","sentence":2,"ask":"How do the ideas about teamwork and laughter support the message?","checks":[{"label":"Mentions bringing people together","rule":{"type":"any","of":[{"type":"contains","any":["together"]},{"type":"contains","any":["connect"]},{"type":"contains","any":["communit"]},{"type":"contains","any":["bond"]}]}},{"label":"Mentions simple activities or the event","rule":{"type":"any","of":[{"type":"contains","any":["simple"]},{"type":"contains","any":["activit"]},{"type":"contains","any":["event"]},{"type":"contains","any":["snowball"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"They show that simple activities can bring people together.","video":"apx_full-8"}]}]}},{"id":"topic_developing_draft","title":"Developing a Draft","short":"Developing a Draft","state":"TX","grade":5,"domain":"Composition","standards":["5.11A","5.11B (i)","5.11B (ii)"],"blurb":"Plan it, outline it, write it — the writing process from prompt to paragraph.","icon":"✏️","core":[{"id":"dd_plan","title":"Planning a First Draft","standards":["5.11A"],"skill":"Topic, audience and purpose — worked out before a word is written","activities":[{"kind":"compose","brief":"Read the prompt. Work out the topic, the audience and the purpose.","hint":"Topic is what it is about. Audience is who reads it. Purpose is what it is for.","items":[{"prompt":"Prompt: Write a letter to the school board explaining why students should have more opportunities for hands-on learning.  What is the TOPIC?","pieces":["Write a letter to the school board explaining why students should have more opportunities for hands-on learning."],"checks":[{"label":"Names hands-on learning","rule":{"type":"contains","any":["hands-on"]}},{"label":"A phrase, not a whole essay","rule":{"type":"minWords","n":2}}],"model":"More hands-on learning in elementary school","video":"dd_plan-1"},{"prompt":"Same prompt. Who is the AUDIENCE?","pieces":["…a letter to the school board…"],"checks":[{"label":"Names the school board","rule":{"type":"contains","any":["school board"]}},{"label":"Written out","rule":{"type":"minWords","n":2}}],"model":"School board members","video":"dd_plan-2"},{"prompt":"Same prompt. What is the PURPOSE?","pieces":["…explaining why students should have more opportunities…"],"checks":[{"label":"Says it is to persuade or convince","rule":{"type":"any","of":[{"type":"contains","any":["persuade"]},{"type":"contains","any":["convince"]},{"type":"contains","any":["support"]}]}},{"label":"Names what they should support","rule":{"type":"contains","any":["hands-on"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"To persuade school leaders to support more hands-on learning","video":"dd_plan-3"},{"prompt":"Prompt: Write an essay explaining the benefits of bike lanes near school zones.  What is the TOPIC?","pieces":["Write an essay explaining the benefits of bike lanes near school zones."],"checks":[{"label":"Names bike lanes","rule":{"type":"contains","any":["bike lane"]}},{"label":"A phrase, not a whole essay","rule":{"type":"minWords","n":3}}],"model":"Benefits of bike lanes near school zones","video":"dd_plan-4"},{"prompt":"Same prompt. Who is the AUDIENCE? (Think about who decides where bike lanes go.)","pieces":["…bike lanes near school zones…"],"checks":[{"label":"Names people who decide","rule":{"type":"any","of":[{"type":"contains","any":["planner"]},{"type":"contains","any":["official"]},{"type":"contains","any":["city"]},{"type":"contains","any":["council"]},{"type":"contains","any":["transportation"]}]}},{"label":"Written out","rule":{"type":"minWords","n":2}}],"model":"City planners and transportation officials","video":"dd_plan-5"},{"prompt":"Same prompt. What is the PURPOSE?","pieces":["…an essay explaining the benefits…"],"checks":[{"label":"Says it is to explain or inform","rule":{"type":"any","of":[{"type":"contains","any":["explain"]},{"type":"contains","any":["inform"]},{"type":"contains","any":["describe"]}]}},{"label":"Names bike lanes","rule":{"type":"contains","any":["bike lane"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":5}}],"model":"To explain the benefits of bike lanes near school zones","video":"dd_plan-6"}]},{"kind":"fix","mode":"select","bank":[],"brief":"Which audience would each word suit — a letter to a friend, or a letter to the school board?","hint":"Casual words for a friend. Careful, formal words for the board.","items":[{"given":"awesome  →  ____","answer":"a friend","options":["a friend","the school board"],"video":"dd_plan-7"},{"given":"cool  →  ____","answer":"a friend","options":["a friend","the school board"]},{"given":"support  →  ____","answer":"the school board","options":["a friend","the school board"]},{"given":"amazing  →  ____","answer":"a friend","options":["a friend","the school board"]},{"given":"address  →  ____","answer":"the school board","options":["a friend","the school board"]},{"given":"numerous  →  ____","answer":"the school board","options":["a friend","the school board"]},{"given":"fun  →  ____","answer":"a friend","options":["a friend","the school board"]},{"given":"beneficial  →  ____","answer":"the school board","options":["a friend","the school board"]},{"given":"instead  →  ____","answer":"the school board","options":["a friend","the school board"]},{"given":"students  →  ____","answer":"the school board","options":["a friend","the school board"]},{"given":"lots  →  ____","answer":"a friend","options":["a friend","the school board"]},{"given":"policies  →  ____","answer":"the school board","options":["a friend","the school board"]}]},{"kind":"compose","brief":"One of topic, audience or purpose is missing. Fill it in.","hint":"Read the two you are given and ask what the third has to be.","items":[{"prompt":"Topic: Students should be able to use artificial intelligence tools for homework.  Audience: Teachers.  PURPOSE?","pieces":["Topic: Students should be able to use AI tools for homework","Audience: Teachers"],"checks":[{"label":"Says it is to persuade","rule":{"type":"any","of":[{"type":"contains","any":["persuade"]},{"type":"contains","any":["convince"]}]}},{"label":"Names teachers","rule":{"type":"contains","any":["teacher"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"To persuade teachers to allow students to use artificial intelligence tools for homework.","video":"dd_plan-8"},{"prompt":"Audience: School board members and community leaders.  Purpose: Persuade readers to support the creation of a school garden.  TOPIC?","pieces":["Audience: School board members and community leaders","Purpose: Persuade readers to support the creation of a school garden"],"checks":[{"label":"Names the garden","rule":{"type":"contains","any":["garden"]}},{"label":"A phrase","rule":{"type":"minWords","n":2}}],"model":"Creating a school garden","video":"dd_plan-9"},{"prompt":"Topic: The local library is adding more digital resources for students.  Purpose: To explain how students can access the new resources.  AUDIENCE?","pieces":["Topic: The library is adding digital resources for students","Purpose: To explain how students can access them"],"checks":[{"label":"Names students","rule":{"type":"contains","any":["student"]}},{"label":"Written out","rule":{"type":"minWords","n":1}}],"model":"Students and families","video":"dd_plan-10"}]},{"kind":"fix","mode":"select","bank":[],"brief":"Two more. Pick the best answer.","hint":"A strong essay topic is specific enough to actually write about.","items":[{"given":"Which topic would be the strongest for an informational essay?  ____","answer":"How solar panels convert sunlight into electricity","options":["How renewable energy can help communities","Renewable energy","Different types of energy sources","How solar panels convert sunlight into electricity"],"video":"dd_plan-11"},{"given":"Who would be the ideal audience for an essay asking for larger libraries?  ____","answer":"the principal and school board members","options":["parents at the school","the principal and school board members","teachers and staff","students who read"],"video":"dd_plan-12"}]}]},{"id":"dd_ideas","title":"Engaging Ideas and Details","standards":["5.11B (ii)"],"skill":"A claim worth making, and the facts that actually hold it up","activities":[{"kind":"passage","brief":"Read the passage. Writing prompt: Should governments invest money in seed banks?","sentences":["Many scientists consider seed banks to be an important resource for protecting plant diversity.","A seed bank is a facility that stores seeds from thousands of plant species under carefully controlled conditions.","These collections help preserve plants that may be threatened by habitat loss, climate change, disease, or natural disasters.","If a plant population declines or disappears in the wild, scientists can use stored seeds to help restore it.","Seed banks also support agricultural research.","Farmers and researchers study stored seeds to develop crops that can better withstand drought, pests, and changing environmental conditions.","Some seed banks contain varieties of plants that are no longer widely grown, making them valuable sources of genetic diversity.","Maintaining these collections requires specialized equipment, regular testing, and long-term planning.","Although seed banks can be expensive to operate, many experts believe they play a critical role in protecting ecosystems and securing future food supplies."],"hint":"A claim takes a side. A fact that supports it has to be about the claim, not just about seeds.","questions":[{"kind":"write","sentence":9,"ask":"Write the claim you would make.","checks":[{"label":"Takes a side","rule":{"type":"any","of":[{"type":"contains","any":["should"]},{"type":"contains","any":["worth"]},{"type":"contains","any":["invest"]},{"type":"contains","any":["important"]}]}},{"label":"Names seed banks","rule":{"type":"contains","any":["seed bank"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":6}}],"model":"Although expensive to start, seed banks are worth the investment.","video":"dd_ideas-1"},{"kind":"blank","sentence":4,"ask":"Which fact most strongly supports that claim?","answer":"If a plant population declines or disappears in the wild, scientists can use stored seeds to help restore it.","options":["If a plant population declines or disappears in the wild, scientists can use stored seeds to help restore it.","Maintaining these collections requires specialized equipment, regular testing, and long-term planning.","A seed bank is a facility that stores seeds from thousands of plant species."],"flag":"Inferred from the passage — the video for questions 2 and 3 shows the fact-sorting boxes but nothing written in them. The paper asks students to sort facts into Important and Less Important; this asks for the strongest one instead.","video":"dd_ideas-2"},{"kind":"blank","sentence":8,"ask":"Which fact is LESS important to the claim?","answer":"Maintaining these collections requires specialized equipment, regular testing, and long-term planning.","options":["Maintaining these collections requires specialized equipment, regular testing, and long-term planning.","Farmers and researchers study stored seeds to develop crops that can better withstand drought, pests, and changing environmental conditions.","These collections help preserve plants that may be threatened by habitat loss, climate change, disease, or natural disasters."],"video":"dd_ideas-2"}]},{"kind":"passage","brief":"A second passage. Read it, then answer.","sentences":["Marine biologists study sea turtles to learn more about their behavior and to help protect their populations.","One challenge researchers face is tracking turtles as they travel across large areas of the ocean.","To solve this problem, scientists attach small satellite transmitters to some turtles.","These devices send location data that allows researchers to follow migration routes and identify important feeding and nesting areas.","The information helps scientists understand where turtles spend their time and what environmental conditions they need to survive.","Tracking studies have also contributed to conservation efforts.","By identifying nesting beaches and migration corridors, researchers can recommend areas that need additional protection.","Data from satellite transmitters has helped scientists recognize threats such as fishing nets, boat traffic, and habitat loss.","As a result, tracking technology has become an important tool for both studying sea turtle behavior and supporting conservation programs designed to protect these animals."],"hint":"Different question, different details. What are you trying to write about each time?","questions":[{"kind":"blank","sentence":2,"ask":"Which detail would you use in a paragraph about HOW scientists study sea turtles?","answer":"One challenge researchers face is tracking turtles as they travel across large areas of the ocean.","options":["One challenge researchers face is tracking turtles as they travel across large areas of the ocean.","Data from satellite transmitters has helped scientists recognize threats such as fishing nets, boat traffic, and habitat loss.","Marine biologists study sea turtles to learn more about their behavior."],"video":"dd_ideas-4"},{"kind":"blank","sentence":8,"ask":"Which detail could you use to argue “Tracking technology helps protect sea turtles”?","answer":"Data from satellite transmitters has helped scientists recognize threats such as fishing nets, boat traffic, and habitat loss.","options":["Data from satellite transmitters has helped scientists recognize threats such as fishing nets, boat traffic, and habitat loss.","One challenge researchers face is tracking turtles as they travel across large areas of the ocean.","To solve this problem, scientists attach small satellite transmitters to some turtles."],"video":"dd_ideas-4"}]},{"kind":"compose","brief":"Make it stronger.","hint":"\"Nice\" is a wish. An argument gives a reason someone else would care about.","items":[{"prompt":"“It would be nice if we had less homework.” Write a more engaging argument for the same idea.","pieces":["It would be nice if we had less homework."],"checks":[{"label":"Keeps the topic","rule":{"type":"contains","any":["homework"]}},{"label":"Gives a reason","rule":{"type":"any","of":[{"type":"contains","any":["because"]},{"type":"contains","any":["so that"]},{"type":"contains","any":["which"]},{"type":"contains","any":["would"]},{"type":"contains","any":["time"]}]}},{"label":"Drops the word nice","rule":{"type":"notContains","any":["nice"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":10}}],"model":"Students with less homework have more time to read, play and rest, which helps them concentrate and learn more in class the next day.","video":"dd_ideas-4"},{"prompt":"Rewrite this to SHOW the action instead of TELLING it: “Raelyn didn’t want to wake up this morning.”","pieces":["Raelyn didn’t want to wake up this morning."],"checks":[{"label":"Keeps Raelyn","rule":{"type":"any","of":[{"type":"contains","any":["raelyn"]},{"type":"contains","any":["she"]}]}},{"label":"Shows an action","rule":{"type":"any","of":[{"type":"contains","any":["groan"]},{"type":"contains","any":["pull"]},{"type":"contains","any":["roll"]},{"type":"contains","any":["bur"]},{"type":"contains","any":["snooze"]},{"type":"contains","any":["blanket"]},{"type":"contains","any":["pillow"]},{"type":"contains","any":["alarm"]},{"type":"contains","any":["eyes"]}]}},{"label":"Stops telling us","rule":{"type":"notContains","any":["didn’t want","didn't want","did not want"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":8}}],"model":"Raelyn groaned, pulled the blanket over her head, and hit snooze for the third time.","video":"dd_ideas-9"}]},{"kind":"fix","mode":"select","bank":[],"brief":"Two more. Pick the best answer.","hint":"Argumentative writing talks to people who disagree with you.","items":[{"given":"Which tone should you use in an argumentative writing assignment?  ____","answer":"formal","options":["casual","presidential","formal","conversational"],"video":"dd_ideas-7"},{"given":"What detail would you include in a writing assignment about shelter pets?  ____","answer":"Shelter pets often cost less to adopt than pets from breeders.","options":["Shelter pets often cost less to adopt than pets from breeders.","Shelter pets are the cutest animals.","Visiting an animal shelter is exciting.","Many people enjoy looking at puppies and kittens."],"video":"dd_ideas-8"}]}]},{"id":"dd_struct","title":"Purposeful Structure","standards":["5.11B (i)"],"skill":"An outline before a paragraph: thesis, main ideas, details, conclusion","flag":"This worksheet is free writing. The paper is a graphic organizer a student fills in and then a paragraph they draft. Structural checks only — they confirm the pieces are there, not that the writing is good. A person reads this before it counts.","activities":[{"kind":"compose","brief":"Prompt: Should schools require every student to participate in at least one club each year? Build the outline.","hint":"The example on the paper: thesis at the top, main ideas on the left, details on the right, conclusion restates the thesis.","items":[{"prompt":"THESIS — the focus of your writing, in one sentence.","pieces":["Should schools require every student to participate in at least one club each year?"],"checks":[{"label":"Takes a side","rule":{"type":"any","of":[{"type":"contains","any":["should"]},{"type":"contains","any":["every student"]},{"type":"contains","any":["require"]}]}},{"label":"Mentions clubs","rule":{"type":"contains","any":["club"]}},{"label":"One sentence","rule":{"type":"minSentences","n":1}}],"model":"Schools should require every student to join at least one club, because clubs build skills and friendships that classes alone cannot.","video":"dd_struct-org1"},{"prompt":"MAIN IDEA 1 is given: “Clubs help students build life skills.” Write a DETAIL that supports it.","pieces":["Main idea: Clubs help students build life skills."],"checks":[{"label":"Names a skill","rule":{"type":"any","of":[{"type":"contains","any":["teamwork"]},{"type":"contains","any":["leader"]},{"type":"contains","any":["responsib"]},{"type":"contains","any":["time"]},{"type":"contains","any":["communicat"]},{"type":"contains","any":["confiden"]},{"type":"contains","any":["skill"]}]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":7}}],"model":"Students who run a club meeting practise leadership and learn to manage their time.","video":"dd_struct-org1"},{"prompt":"The DETAILS are given: “Students often make new friends with similar interests. Being involved helps students feel like they belong.” Write MAIN IDEA 2.","pieces":["Details: Students often make new friends with similar interests. Being involved helps students feel like they belong."],"checks":[{"label":"About friends or belonging","rule":{"type":"any","of":[{"type":"contains","any":["friend"]},{"type":"contains","any":["belong"]},{"type":"contains","any":["connect"]},{"type":"contains","any":["communit"]}]}},{"label":"Mentions clubs","rule":{"type":"contains","any":["club"]}},{"label":"One sentence","rule":{"type":"minSentences","n":1}}],"model":"Clubs help students make friends and feel that they belong at school.","video":"dd_struct-org1"},{"prompt":"MAIN IDEA 3 and one DETAIL — your own.","checks":[{"label":"Mentions clubs","rule":{"type":"contains","any":["club"]}},{"label":"At least two sentences","rule":{"type":"minSentences","n":2}},{"label":"Long enough to be an idea and a detail","rule":{"type":"minWords","n":14}}],"model":"Clubs let students try things they cannot try in class. A student who joins the robotics club may discover a career before they are twelve.","video":"dd_struct-org1"},{"prompt":"CONCLUSION — restate the thesis.","checks":[{"label":"Mentions clubs","rule":{"type":"contains","any":["club"]}},{"label":"Sounds like an ending","rule":{"type":"any","of":[{"type":"contains","any":["as you can see"]},{"type":"contains","any":["in conclusion"]},{"type":"contains","any":["overall"]},{"type":"contains","any":["for these reasons"]},{"type":"contains","any":["that is why"]},{"type":"contains","any":["clearly"]}]}},{"label":"One sentence","rule":{"type":"minSentences","n":1}}],"model":"As you can see, requiring every student to join a club would give them skills, friends and a place to belong.","video":"dd_struct-org1"}]},{"kind":"compose","brief":"Now the whole thing. Should students have school on Fridays? Outline it, then draft the paragraph.","hint":"Thesis. Three main ideas with details. Conclusion. Then turn the outline into sentences.","items":[{"prompt":"Your OUTLINE: thesis, three main ideas, conclusion.","pieces":["Should students have school on Fridays?"],"checks":[{"label":"Mentions Friday","rule":{"type":"contains","any":["friday"]}},{"label":"Takes a side","rule":{"type":"any","of":[{"type":"contains","any":["should"]},{"type":"contains","any":["should not"]},{"type":"contains","any":["shouldn't"]}]}},{"label":"Has several parts","rule":{"type":"minSentences","n":4}},{"label":"Long enough for an outline","rule":{"type":"minWords","n":40}}],"model":"Thesis: Students should not have school on Fridays. Main idea 1: A four-day week gives students a day to rest and catch up. Main idea 2: Families would have more time together. Main idea 3: Schools would save money on buses and buildings. Conclusion: For these reasons, a four-day school week would help students and schools alike.","video":"dd_struct-org2"},{"prompt":"Your DRAFT — the paragraph, written from your outline.","checks":[{"label":"Mentions Friday","rule":{"type":"contains","any":["friday"]}},{"label":"Opens with a position","rule":{"type":"any","of":[{"type":"contains","any":["should"]},{"type":"contains","any":["should not"]},{"type":"contains","any":["shouldn't"]}]}},{"label":"Gives reasons","rule":{"type":"any","of":[{"type":"contains","any":["because"]},{"type":"contains","any":["first"]},{"type":"contains","any":["also"]},{"type":"contains","any":["another"]}]}},{"label":"Ends with a conclusion","rule":{"type":"any","of":[{"type":"contains","any":["in conclusion"]},{"type":"contains","any":["overall"]},{"type":"contains","any":["for these reasons"]},{"type":"contains","any":["that is why"]},{"type":"contains","any":["as you can see"]}]}},{"label":"A real paragraph","rule":{"type":"minWords","n":60}}],"model":"Students should not have school on Fridays. First, a four-day week would give students a day to rest and catch up on work, so they arrive on Monday ready to learn. Families would also have more time together, which matters as much as any lesson. Finally, schools would save money on buses and buildings that could go towards teachers and books instead. For these reasons, a four-day school week would help students and schools alike.","video":"dd_struct-org2"}]}]}],"skillBuilders":{},"full":{"id":"dd_full","title":"Full Topic: Develop a Draft","standards":["5.11A","5.11B (i)","5.11B (ii)"],"skill":"Plan it, outline it, write it","flag":"The deck for this capstone says GRADE 4 where every other worksheet in the topic says Grade 5. The paper needs checking. The draft itself is free writing. Structural checks only — they confirm the pieces are there, not that the writing is good. A person reads this before it counts.","activities":[{"kind":"compose","brief":"Prompt: Write a paragraph to students about whether they should play a sport after school. Topic, audience, purpose.","hint":"Three short answers.","items":[{"prompt":"TOPIC?","pieces":["Write a paragraph to students about whether they should play a sport after school."],"checks":[{"label":"Names sport","rule":{"type":"contains","any":["sport"]}},{"label":"A phrase","rule":{"type":"minWords","n":2}}],"model":"Sports after school","video":"dd_full-org1"},{"prompt":"AUDIENCE?","pieces":["…a paragraph to students…"],"checks":[{"label":"Names students","rule":{"type":"contains","any":["student"]}}],"model":"Students","video":"dd_full-org1"},{"prompt":"PURPOSE?","pieces":["…about whether they should play a sport…"],"checks":[{"label":"Says persuade or explain","rule":{"type":"any","of":[{"type":"contains","any":["persuade"]},{"type":"contains","any":["convince"]},{"type":"contains","any":["explain"]},{"type":"contains","any":["help"]}]}},{"label":"Names sport","rule":{"type":"contains","any":["sport"]}},{"label":"Written as a sentence","rule":{"type":"minWords","n":5}}],"model":"To persuade students to play a sport after school.","flag":"The video for this page fills in topic and audience and leaves purpose blank. The model answer is mine.","video":"dd_full-org1"}]},{"kind":"compose","brief":"Should students play a sport after school? Outline it.","hint":"Thesis, three main ideas with details, conclusion.","items":[{"prompt":"Your OUTLINE.","checks":[{"label":"Mentions sport","rule":{"type":"contains","any":["sport"]}},{"label":"Takes a side","rule":{"type":"contains","any":["should"]}},{"label":"Has several parts","rule":{"type":"minSentences","n":4}},{"label":"Long enough for an outline","rule":{"type":"minWords","n":40}}],"model":"Thesis: Students should play a sport after school. Main idea 1: Sport keeps students healthy and active. Main idea 2: Being on a team teaches students to work with others. Main idea 3: Sport gives students a break from screens and homework. Conclusion: For these reasons, every student should try a sport after school.","video":"dd_full-org1"}]},{"kind":"compose","brief":"Now write it. Your response should have a clear central idea, descriptive details with specific examples, proper language, and a conclusion that supports the central idea.","hint":"That list is the rubric. Check your draft against each line.","items":[{"prompt":"Your RESPONSE.","checks":[{"label":"A clear central idea","rule":{"type":"all","of":[{"type":"contains","any":["sport"]},{"type":"contains","any":["should"]}]}},{"label":"Specific examples","rule":{"type":"any","of":[{"type":"contains","any":["for example"]},{"type":"contains","any":["such as"]},{"type":"contains","any":["like"]},{"type":"contains","any":["soccer"]},{"type":"contains","any":["basketball"]},{"type":"contains","any":["swim"]},{"type":"contains","any":["run"]},{"type":"contains","any":["team"]}]}},{"label":"Proper language","rule":{"type":"notContains","any":["gonna","wanna","kinda"," u ","lol"]}},{"label":"A conclusion","rule":{"type":"any","of":[{"type":"contains","any":["in conclusion"]},{"type":"contains","any":["overall"]},{"type":"contains","any":["for these reasons"]},{"type":"contains","any":["that is why"]},{"type":"contains","any":["as you can see"]}]}},{"label":"Long enough to be a response","rule":{"type":"minWords","n":80}}],"model":"Students should play a sport after school. Sport keeps students healthy and active: an hour of soccer or basketball burns off the energy that builds up during a day at a desk. Being on a team also teaches students to work with others, because a team only wins when everyone passes the ball. Finally, a sport gives students a real break from screens and homework, and most come home calmer and ready to focus. For these reasons, every student should try at least one sport after school.","video":"dd_full-org2"}]}]}}]
